"use client";

import { useState, useEffect, useCallback } from "react";
import { adminApi } from "@/lib/api/admin";
import { BookMarked, Building2, ChevronDown, ChevronRight, AlertCircle, RefreshCw, Loader2 } from "lucide-react";

interface Faculty    { id: string; name: string }
interface Department { id: string; name: string; shortCode?: string }

export default function AdminStructurePage() {
  const [faculties, setFaculties]   = useState<Faculty[]>([]);
  const [depts, setDepts]           = useState<Record<string, Department[]>>({});
  const [expanded, setExpanded]     = useState<Record<string, boolean>>({});
  const [loading, setLoading]       = useState(true);
  const [deptLoading, setDeptLoad]  = useState<Record<string, boolean>>({});
  const [error, setError]           = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const data = await adminApi.getSchoolAdminFaculties();
      setFaculties(Array.isArray(data) ? data : []);
    } catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  async function toggle(faculty: Faculty) {
    const next = !expanded[faculty.id];
    setExpanded(p => ({ ...p, [faculty.id]: next }));
    if (next && !depts[faculty.id]) {
      setDeptLoad(p => ({ ...p, [faculty.id]: true }));
      try {
        const data = await adminApi.getSchoolAdminDepartments(faculty.id);
        setDepts(p => ({ ...p, [faculty.id]: Array.isArray(data) ? data : [] }));
      } catch (e: any) { setError(e.message); }
      finally { setDeptLoad(p => ({ ...p, [faculty.id]: false })); }
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Faculties & Departments</h1>
          <p className="text-muted-foreground text-sm mt-1">Your school's academic structure (read-only)</p>
        </div>
        <button onClick={load} disabled={loading} className="p-2 rounded-xl border border-border hover:bg-accent disabled:opacity-50 transition-colors">
          <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
        </button>
      </div>

      {error && (
        <div className="bg-destructive/10 text-destructive rounded-xl p-4 flex items-center gap-2 text-sm">
          <AlertCircle className="w-4 h-4 shrink-0" /> {error}
        </div>
      )}

      {loading ? (
        <div className="flex flex-col gap-3">
          {Array.from({ length: 5 }).map((_, i) => <div key={i} className="bg-card rounded-2xl p-4 h-14 animate-pulse" />)}
        </div>
      ) : faculties.length === 0 ? (
        <div className="bg-card rounded-2xl p-10 text-center text-muted-foreground text-sm">
          No faculties found for your school.
        </div>
      ) : (
        <div className="flex flex-col gap-2">
          {faculties.map(faculty => (
            <div key={faculty.id} className="bg-card rounded-2xl overflow-hidden">
              <button
                onClick={() => toggle(faculty)}
                className="w-full flex items-center gap-3 px-4 py-3.5 text-left"
              >
                {expanded[faculty.id]
                  ? <ChevronDown className="w-4 h-4 text-muted-foreground shrink-0" />
                  : <ChevronRight className="w-4 h-4 text-muted-foreground shrink-0" />
                }
                <BookMarked className="w-4 h-4 text-primary shrink-0" />
                <span className="flex-1 font-medium text-foreground text-sm">{faculty.name}</span>
                {depts[faculty.id] && (
                  <span className="text-xs text-muted-foreground shrink-0">{depts[faculty.id].length} dept{depts[faculty.id].length !== 1 ? "s" : ""}</span>
                )}
              </button>

              {expanded[faculty.id] && (
                <div className="border-t border-border px-4 py-2">
                  {deptLoading[faculty.id] ? (
                    <div className="flex items-center gap-2 py-3 text-muted-foreground text-sm">
                      <Loader2 className="w-4 h-4 animate-spin" /> Loading departments…
                    </div>
                  ) : !depts[faculty.id] || depts[faculty.id].length === 0 ? (
                    <p className="text-xs text-muted-foreground py-2 pl-6">No departments.</p>
                  ) : (
                    depts[faculty.id].map(dept => (
                      <div key={dept.id} className="flex items-center gap-2 py-2 pl-6 border-b border-border last:border-0">
                        <Building2 className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                        <span className="text-sm text-foreground flex-1">{dept.name}</span>
                        {dept.shortCode && (
                          <span className="text-xs text-muted-foreground bg-muted rounded-lg px-2 py-0.5">{dept.shortCode}</span>
                        )}
                      </div>
                    ))
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Loader2, TrendingUp, Users, BarChart3, CheckCircle } from "lucide-react";
import { getAdminQuizAnalytics, listQuizzes } from "@/lib/api/study.api";
import type { Quiz } from "@/types/study";

export default function AdminQuizAnalyticsPage() {
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedQuizId, setSelectedQuizId] = useState<string | null>(null);
  const [analytics, setAnalytics] = useState<any>(null);

  useEffect(() => {
    const loadQuizzes = async () => {
      try {
        const data = await listQuizzes({ limit: 100 });
        const quizList = data.data || [];
        setQuizzes(quizList);
        if (quizList.length > 0) {
          setSelectedQuizId(quizList[0].id);
        }
      } catch (error) {
        console.error("Failed to load quizzes:", error);
      } finally {
        setLoading(false);
      }
    };
    loadQuizzes();
  }, []);

  useEffect(() => {
    if (!selectedQuizId) return;

    const loadAnalytics = async () => {
      try {
        const data = await getAdminQuizAnalytics({ quizId: selectedQuizId });
        setAnalytics(data);
      } catch (error) {
        console.error("Failed to load analytics:", error);
      }
    };
    loadAnalytics();
  }, [selectedQuizId]);

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const selectedQuiz = quizzes.find((q) => q.id === selectedQuizId);

  return (
    <div>
      <h2 className="text-2xl font-bold text-foreground mb-6">Quiz Analytics</h2>

      {/* Top Stats */}
      {analytics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
          <div className="bg-card rounded-2xl p-6 border border-border">
            <div className="flex items-center gap-3 mb-3">
              <Users className="w-6 h-6 text-primary" />
              <h3 className="font-medium text-foreground">Attempts</h3>
            </div>
            <p className="text-3xl font-bold text-foreground">
              {analytics.totalAttempts || 0}
            </p>
          </div>

          <div className="bg-card rounded-2xl p-6 border border-border">
            <div className="flex items-center gap-3 mb-3">
              <BarChart3 className="w-6 h-6 text-purple-600" />
              <h3 className="font-medium text-foreground">Avg Score</h3>
            </div>
            <p className="text-3xl font-bold text-foreground">
              {analytics.averageScore ? analytics.averageScore.toFixed(1) : "0"}%
            </p>
          </div>

          <div className="bg-card rounded-2xl p-6 border border-border">
            <div className="flex items-center gap-3 mb-3">
              <TrendingUp className="w-6 h-6 text-green-600" />
              <h3 className="font-medium text-foreground">Pass Rate</h3>
            </div>
            <p className="text-3xl font-bold text-foreground">
              {analytics.passRate || "0"}%
            </p>
          </div>

          <div className="bg-card rounded-2xl p-6 border border-border">
            <div className="flex items-center gap-3 mb-3">
              <CheckCircle className="w-6 h-6 text-emerald-600" />
              <h3 className="font-medium text-foreground">Students</h3>
            </div>
            <p className="text-3xl font-bold text-foreground">
              {analytics.uniqueStudents || 0}
            </p>
          </div>
        </div>
      )}

      {/* Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Quiz List */}
        <div className="lg:col-span-1">
          <div className="bg-card rounded-2xl p-6 border border-border">
            <h3 className="font-bold text-foreground mb-4">Quizzes</h3>
            <div className="space-y-2 max-h-96 overflow-y-auto">
              {quizzes.map((quiz) => (
                <button
                  key={quiz.id}
                  onClick={() => setSelectedQuizId(quiz.id)}
                  className={`w-full text-left px-4 py-3 rounded-lg transition-colors ${
                    selectedQuizId === quiz.id
                      ? "bg-primary text-primary-foreground"
                      : "hover:bg-accent text-foreground"
                  }`}
                >
                  <p className="font-medium text-sm line-clamp-1">{quiz.title}</p>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Details */}
        <div className="lg:col-span-3">
          {selectedQuiz && (
            <div className="bg-card rounded-2xl p-6 border border-border">
              <h3 className="font-bold text-foreground mb-4">{selectedQuiz.title}</h3>
              <div className="space-y-3 text-sm">
                {selectedQuiz.description && (
                  <div>
                    <p className="text-muted-foreground uppercase text-xs tracking-wider mb-1">Description</p>
                    <p className="text-foreground">{selectedQuiz.description}</p>
                  </div>
                )}
                <div>
                  <p className="text-muted-foreground uppercase text-xs tracking-wider mb-1">Questions</p>
                  <p className="text-foreground font-medium">{selectedQuiz.questions?.length || 0}</p>
                </div>
                <div>
                  <p className="text-muted-foreground uppercase text-xs tracking-wider mb-1">Created</p>
                  <p className="text-foreground">
                    {new Date(selectedQuiz.createdAt).toLocaleDateString()}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { listUsers, assignRole, nominateCourseRep } from "@/lib/api/users.api";
import type { UserProfile } from "@/types/users";

export default function UsersListPage() {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [role, setRole] = useState("");
  const limit = 20;

  const refresh = () => {
    listUsers({ page, limit, role }).then(res => {
      setUsers(res.data);
      setTotal(res.total);
    });
  };

  useEffect(() => { refresh(); }, [page, role]);

  const handleAssignRole = async (userId: string, newRole: string) => {
    await assignRole({ userId, role: newRole });
    refresh();
  };

  const handleNominate = async (userId: string) => {
    await nominateCourseRep({ userId });
    alert("Nominated as course rep");
  };

  return (
    <div>
      <h1 className="text-2xl font-bold mb-4">All Users</h1>
      <div className="mb-4">
        <select value={role} onChange={e => setRole(e.target.value)} className="border p-2">
          <option value="">All Roles</option>
          <option value="STUDENT">Student</option>
          <option value="COURSE_REP">Course Rep</option>
          <option value="MODERATOR">Moderator</option>
          <option value="ADMIN">Admin</option>
        </select>
      </div>
      <table className="w-full bg-card shadow rounded">
        <thead className="bg-muted">
          <tr>
            <th className="p-2 text-left">Name</th>
            <th className="p-2 text-left">Email</th>
            <th className="p-2 text-left">Role</th>
            <th className="p-2 text-right">Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map(u => (
            <tr key={u.id} className="border-t">
              <td className="p-2">{u.name}</td>
              <td className="p-2">{u.email}</td>
              <td className="p-2">{u.role}</td>
              <td className="p-2 text-right">
                <button onClick={() => handleNominate(u.id)} className="text-primary mr-2">Nominate CR</button>
                <select
                  className="border p-1"
                  value={u.role}
                  onChange={e => handleAssignRole(u.id, e.target.value)}
                >
                  <option value="STUDENT">Student</option>
                  <option value="COURSE_REP">Course Rep</option>
                  <option value="MODERATOR">Moderator</option>
                  <option value="ADMIN">Admin</option>
                </select>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="flex justify-between mt-4">
        <button disabled={page <= 1} onClick={() => setPage(p => p - 1)} className="btn">Prev</button>
        <span>Page {page}</span>
        <button disabled={page * limit >= total} onClick={() => setPage(p => p + 1)} className="btn">Next</button>
      </div>
    </div>
  );
}

