"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { CommunityHeader } from "@/components/community/CommunityHeader";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { registerMentor } from "@/lib/api/community.api";

export default function RegisterMentorPage() {
  const router = useRouter();
  const [expertiseInput, setExpertiseInput] = useState("");
  const [expertiseList, setExpertiseList] = useState<string[]>([]);
  const [bio, setBio] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleAddExpertise = () => {
    const trimmed = expertiseInput.trim();
    if (trimmed && !expertiseList.includes(trimmed)) {
      setExpertiseList([...expertiseList, trimmed]);
      setExpertiseInput("");
    }
  };

  const removeExpertise = (item: string) => {
    setExpertiseList(expertiseList.filter((e) => e !== item));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (expertiseList.length === 0) {
      setError("Add at least one area of expertise.");
      return;
    }
    if (!bio.trim()) {
      setError("Bio is required.");
      return;
    }

    setLoading(true);
    setError("");

    try {
      await registerMentor({ expertise: expertiseList, bio });
      router.push("/community/mentors");
    } catch (err: any) {
      setError(err.message || "Failed to register as mentor");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pb-24 max-w-2xl mx-auto">
      <CommunityHeader title="Become a Mentor" />

      <form onSubmit={handleSubmit} className="space-y-5">
        {error && <ErrorMessage message={error} />}

        <div>
          <label className="block text-sm font-medium text-foreground mb-1">
            Areas of Expertise
          </label>
          <div className="flex gap-2">
            <input
              type="text"
              value={expertiseInput}
              onChange={(e) => setExpertiseInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && (e.preventDefault(), handleAddExpertise())}
              placeholder="e.g. JavaScript, Calculus"
              className="flex-1 rounded-xl border border-border bg-background px-4 py-2.5 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
            />
            <Button type="button" variant="outline" onClick={handleAddExpertise}>
              Add
            </Button>
          </div>
          {expertiseList.length > 0 && (
            <div className="flex flex-wrap gap-2 mt-3">
              {expertiseList.map((item) => (
                <span
                  key={item}
                  className="bg-primary/10 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-1"
                >
                  {item}
                  <button
                    type="button"
                    onClick={() => removeExpertise(item)}
                    className="text-primary hover:text-primary/70"
                  >
                    ×
                  </button>
                </span>
              ))}
            </div>
          )}
        </div>

        <div>
          <label htmlFor="bio" className="block text-sm font-medium text-foreground mb-1">
            Bio
          </label>
          <textarea
            id="bio"
            value={bio}
            onChange={(e) => setBio(e.target.value)}
            placeholder="Tell students about yourself, your experience, and how you can help..."
            className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring h-32 resize-none"
            required
          />
        </div>

        <div className="flex justify-end gap-3">
          <Button variant="outline" type="button" onClick={() => router.back()}>
            Cancel
          </Button>
          <Button type="submit" disabled={loading}>
            {loading ? "Registering..." : "Register as Mentor"}
          </Button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { MessageSquare, HelpCircle, Users, BookOpen, Plus, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { CommunityCard } from "@/components/community/CommunityCard";
import { CommunityEmptyState } from "@/components/community/CommunityEmptyState";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { listPosts, listQuestions } from "@/lib/api/community.api";
import type { Post, Question } from "@/types/community";

const QUICK_ACTIONS = [
  {
    title: "Posts",
    description: "Share updates, announcements, and engage with your community",
    icon: MessageSquare,
    href: "/community/posts",
    color: "bg-primary/10 text-primary",
  },
  {
    title: "Questions & Answers",
    description: "Ask questions and help others learn",
    icon: HelpCircle,
    href: "/community/questions",
    color: "bg-primary/10 text-primary",
  },
  {
    title: "Mentors",
    description: "Find mentors or become one for your courses",
    icon: Users,
    href: "/community/mentors",
    color: "bg-success/10 text-success",
  },
  {
    title: "FAQ",
    description: "Frequently asked questions from your community",
    icon: BookOpen,
    href: "/community/faq",
    color: "bg-warning/10 text-warning",
  },
];

export default function CommunityHome() {
  const [recentPosts, setRecentPosts] = useState<Post[]>([]);
  const [recentQuestions, setRecentQuestions] = useState<Question[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [postsRes, questionsRes] = await Promise.all([
          listPosts({ page: 1, limit: 3 }),
          listQuestions({ page: 1, limit: 3 }),
        ]);
        setRecentPosts(postsRes.data);
        setRecentQuestions(questionsRes.data);
      } catch (err: any) {
        setError(err.message || "Failed to load community activity");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  if (error) {
    return <ErrorMessage message={error} />;
  }

  return (
    <div className="pb-24 space-y-8">
      {/* Hero Section */}
      <div className="bg-card rounded-2xl p-6 border border-border shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
            <Sparkles className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-foreground">Community Hub</h1>
            <p className="text-sm text-muted-foreground">
              Connect, learn, and grow with your fellow students
            </p>
          </div>
        </div>
        <div className="mt-4 flex flex-wrap gap-3">
          <Button asChild>
            <Link href="/community/posts/new">
              <Plus className="w-4 h-4 mr-1.5" />
              Create Post
            </Link>
          </Button>
          <Button variant="outline" asChild>
            <Link href="/community/questions/new">
              <HelpCircle className="w-4 h-4 mr-1.5" />
              Ask Question
            </Link>
          </Button>
        </div>
      </div>

      {/* Quick Actions Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {QUICK_ACTIONS.map(({ title, description, icon: Icon, href, color }) => (
          <Link
            key={href}
            href={href}
            className="block bg-card rounded-2xl p-5 border border-border shadow-sm hover:shadow-md transition-all hover:-translate-y-0.5 active:scale-95"
          >
            <div className={`w-11 h-11 rounded-xl ${color} flex items-center justify-center mb-3`}>
              <Icon className="w-5 h-5" />
            </div>
            <h3 className="font-semibold text-foreground text-sm">{title}</h3>
            <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{description}</p>
          </Link>
        ))}
      </div>

      {/* Recent Activity */}
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-foreground">Recent Activity</h2>
          <Button variant="ghost" size="sm" asChild>
            <Link href="/community/posts">View all</Link>
          </Button>
        </div>

        {loading ? (
          <LoadingSkeleton count={2} height="h-24" />
        ) : (
          <>
            {recentPosts.length === 0 && recentQuestions.length === 0 && (
              <CommunityEmptyState
                icon={<MessageSquare className="w-8 h-8" />}
                title="No activity yet"
                description="Be the first to start a discussion or ask a question!"
                action={
                  <Button asChild>
                    <Link href="/community/posts/new">Create Post</Link>
                  </Button>
                }
              />
            )}

            {recentPosts.map((post) => (
              <CommunityCard key={post.id}>
                <div>
                  <Link
                    href={`/community/posts/${post.id}`}
                    className="font-medium text-foreground hover:text-primary transition-colors"
                  >
                    {post.title}
                  </Link>
                  <p className="text-sm text-muted-foreground line-clamp-1 mt-0.5">
                    {post.content}
                  </p>
                  <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                    <span>{post.author.name}</span>
                    <span>{post.upvotes} upvotes</span>
                    <span>{post.comments.length} comments</span>
                  </div>
                </div>
              </CommunityCard>
            ))}

            {recentQuestions.map((q) => (
              <CommunityCard key={q.id}>
                <div>
                  <Link
                    href={`/community/questions/${q.id}`}
                    className="font-medium text-foreground hover:text-primary transition-colors"
                  >
                    {q.title}
                  </Link>
                  <p className="text-sm text-muted-foreground line-clamp-1 mt-0.5">
                    {q.content}
                  </p>
                  <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                    <span>{q.author.name}</span>
                    <span>{q.upvotes} upvotes</span>
                    <span>{q.answers.length} answers</span>
                  </div>
                </div>
              </CommunityCard>
            ))}
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { ThumbsUp, MessageSquare, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { CommunityHeader } from "@/components/community/CommunityHeader";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { getPost, createComment, upvotePost, report } from "@/lib/api/community.api";
import type { Post } from "@/types/community";

export default function PostDetail() {
  const { id } = useParams<{ id: string }>();
  const [post, setPost] = useState<Post | null>(null);
  const [comment, setComment] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reportError, setReportError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPost = async () => {
      setLoading(true);
      try {
        const data = await getPost(id);
        setPost(data);
      } catch (err: any) {
        setError(err.message || "Post not found");
      } finally {
        setLoading(false);
      }
    };
    fetchPost();
  }, [id]);

  const handleComment = async () => {
    if (!comment.trim()) return;
    setSubmitting(true);
    try {
      const newComment = await createComment(id, { content: comment });
      setPost((prev) =>
        prev ? { ...prev, comments: [...prev.comments, newComment] } : prev
      );
      setComment("");
    } catch (err: any) {
      alert(err.message || "Failed to post comment");
    } finally {
      setSubmitting(false);
    }
  };

  const handleUpvote = async () => {
    if (!post) return;
    try {
      await upvotePost(post.id);
      setPost({ ...post, upvotes: post.upvotes + 1 });
    } catch (err: any) {
      alert(err.message || "Failed to upvote");
    }
  };

  const handleReport = async () => {
    if (!confirm("Report this post as inappropriate?")) return;
    try {
      await report(id, { reason: "Inappropriate content", type: "POST" });
      setReportError("Report submitted successfully.");
      setTimeout(() => setReportError(null), 3000);
    } catch (err: any) {
      alert(err.message || "Failed to report");
    }
  };

  if (loading) {
    return (
      <div className="pb-24">
        <LoadingSkeleton count={1} height="h-48" />
        <div className="mt-6 space-y-4">
          <LoadingSkeleton count={2} height="h-20" />
        </div>
      </div>
    );
  }

  if (error || !post) {
    return <ErrorMessage message={error || "Post not found"} />;
  }

  return (
    <div className="pb-24">
      <CommunityHeader title={post.title} />

      <div className="space-y-6">
        <Card>
          <CardContent className="p-5 space-y-4">
            <div className="flex items-center justify-between text-sm text-muted-foreground">
              <span>by {post.author.name}</span>
              <span>{new Date(post.createdAt).toLocaleDateString()}</span>
            </div>
            <div className="prose prose-sm max-w-none text-foreground">
              {post.content}
            </div>
            <div className="flex flex-wrap items-center gap-4 pt-2 border-t border-border">
              <Button size="sm" variant="outline" onClick={handleUpvote}>
                <ThumbsUp className="w-4 h-4 mr-1.5" />
                {post.upvotes}
              </Button>
              <Button size="sm" variant="ghost" onClick={handleReport}>
                <AlertCircle className="w-4 h-4 mr-1.5" />
                Report
              </Button>
              {reportError && (
                <span className="text-sm text-success">{reportError}</span>
              )}
            </div>
          </CardContent>
        </Card>

        <div>
          <h2 className="text-lg font-semibold text-foreground mb-4">
            Comments ({post.comments.length})
          </h2>
          {post.comments.length === 0 ? (
            <p className="text-sm text-muted-foreground">No comments yet.</p>
          ) : (
            <div className="space-y-3">
              {post.comments.map((c) => (
                <Card key={c.id}>
                  <CardContent className="p-4 space-y-1">
                    <div className="flex items-center justify-between text-sm">
                      <span className="font-medium">{c.author.name}</span>
                      <span className="text-xs text-muted-foreground">
                        {new Date(c.createdAt).toLocaleDateString()}
                      </span>
                    </div>
                    <p className="text-sm">{c.content}</p>
                    <p className="text-xs text-muted-foreground">
                      {c.upvotes} upvotes
                    </p>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>

        <div className="flex gap-3">
          <input
            type="text"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            placeholder="Write a comment..."
            className="flex-1 rounded-xl border border-border bg-background px-4 py-2 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
          />
          <Button onClick={handleComment} disabled={submitting || !comment.trim()}>
            Send
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { CommunityHeader } from "@/components/community/CommunityHeader";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { createPost } from "@/lib/api/community.api";
import type { PostSection } from "@/types/community";

export default function NewPost() {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [section, setSection] = useState<PostSection>("GENERAL");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      await createPost({ title, content, section });
      router.push("/community/posts");
    } catch (err: any) {
      setError(err.message || "Failed to create post");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pb-24 max-w-2xl mx-auto">
      <CommunityHeader title="Create Post" />

      <form onSubmit={handleSubmit} className="space-y-5">
        {error && <ErrorMessage message={error} />}
        <div>
          <label htmlFor="title" className="block text-sm font-medium text-foreground mb-1">
            Title
          </label>
          <input
            id="title"
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="What's on your mind?"
            className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
            required
          />
        </div>
        <div>
          <label htmlFor="section" className="block text-sm font-medium text-foreground mb-1">
            Category
          </label>
          <select
            id="section"
            value={section}
            onChange={(e) => setSection(e.target.value as PostSection)}
            className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
          >
            <option value="GENERAL">General</option>
            <option value="ACADEMICS">Academics</option>
            <option value="CAREER">Career</option>
            <option value="EVENTS">Events</option>
            <option value="NOTICE_BOARD">Notice Board</option>
          </select>
        </div>
        <div>
          <label htmlFor="content" className="block text-sm font-medium text-foreground mb-1">
            Content
          </label>
          <textarea
            id="content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Write your post here..."
            className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring h-40 resize-none"
            required
          />
        </div>
        <div className="flex justify-end gap-3">
          <Button variant="outline" type="button" onClick={() => router.back()}>
            Cancel
          </Button>
          <Button type="submit" disabled={loading}>
            {loading ? "Publishing..." : "Publish"}
          </Button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { CommunityHeader } from "@/components/community/CommunityHeader";
import { PostCard } from "@/components/community/PostCard";
import { CommunityEmptyState } from "@/components/community/CommunityEmptyState";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { Pagination } from "@/components/ui/Pagination";
import { listPosts, deletePost, pinPost } from "@/lib/api/community.api";
import type { Post } from "@/types/community";

export default function PostsList() {
  const [posts, setPosts] = useState<Post[]>([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const limit = 10;

  useEffect(() => {
    const fetchPosts = async () => {
      setLoading(true);
      try {
        const res = await listPosts({ page, limit });
        setPosts(res.data);
        setTotal(res.total);
      } catch (err: any) {
        setError(err.message || "Failed to load posts");
      } finally {
        setLoading(false);
      }
    };
    fetchPosts();
  }, [page]);

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this post?")) return;
    try {
      await deletePost(id);
      setPosts((prev) => prev.filter((p) => p.id !== id));
      setTotal((t) => t - 1);
    } catch (err: any) {
      alert(err.message || "Failed to delete post");
    }
  };

  const handlePin = async (id: string, isPinned: boolean) => {
    try {
      await pinPost(id, !isPinned);
      setPosts((prev) =>
        prev.map((p) => (p.id === id ? { ...p, isPinned: !isPinned } : p))
      );
    } catch (err: any) {
      alert(err.message || "Failed to update pin status");
    }
  };

  if (error) {
    return <ErrorMessage message={error} />;
  }

  return (
    <div className="pb-24">
      <CommunityHeader
        title="Discussion Posts"
        description="Share updates, announcements, and engage with the community"
        action={
          <Button asChild>
            <Link href="/community/posts/new">
              <Plus className="w-4 h-4 mr-1.5" />
              New Post
            </Link>
          </Button>
        }
      />

      {loading ? (
        <LoadingSkeleton count={3} height="h-28" />
      ) : (
        <>
          {posts.length === 0 ? (
            <CommunityEmptyState
              icon={<Plus className="w-8 h-8" />}
              title="No posts yet"
              description="Start a new discussion and be the first to post!"
              action={
                <Button asChild>
                  <Link href="/community/posts/new">Create Post</Link>
                </Button>
              }
            />
          ) : (
            <div className="space-y-4">
              {posts.map((post) => (
                <PostCard
                  key={post.id}
                  post={post}
                  onPin={handlePin}
                  onDelete={handleDelete}
                  showActions
                />
              ))}
            </div>
          )}

          {total > limit && (
            <Pagination
              currentPage={page}
              totalPages={Math.ceil(total / limit)}
              onPageChange={setPage}
              showPageNumber
            />
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { ThumbsUp, CheckCircle, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { CommunityHeader } from "@/components/community/CommunityHeader";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import {
  getQuestion,
  createAnswer,
  upvoteQuestion,
  acceptAnswer,
  report,
} from "@/lib/api/community.api";
import type { Question, Answer } from "@/types/community";

export default function QuestionDetail() {
  const { id } = useParams<{ id: string }>();
  const [question, setQuestion] = useState<Question | null>(null);
  const [answer, setAnswer] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reportSuccess, setReportSuccess] = useState<string | null>(null);

  useEffect(() => {
    const fetchQuestion = async () => {
      setLoading(true);
      try {
        const data = await getQuestion(id);
        setQuestion(data);
      } catch (err: any) {
        setError(err.message || "Question not found");
      } finally {
        setLoading(false);
      }
    };
    fetchQuestion();
  }, [id]);

  const handleAnswerSubmit = async () => {
    if (!answer.trim()) return;
    setSubmitting(true);
    try {
      const newAns = await createAnswer(id, { content: answer });
      setQuestion((prev) =>
        prev ? { ...prev, answers: [...prev.answers, newAns] } : prev
      );
      setAnswer("");
    } catch (err: any) {
      alert(err.message || "Failed to post answer");
    } finally {
      setSubmitting(false);
    }
  };

  const handleUpvote = async () => {
    if (!question) return;
    try {
      await upvoteQuestion(question.id);
      setQuestion({ ...question, upvotes: question.upvotes + 1 });
    } catch (err: any) {
      alert(err.message || "Failed to upvote");
    }
  };

  const handleAccept = async (answerId: string) => {
    try {
      await acceptAnswer(id, answerId);
      setQuestion((prev) =>
        prev
          ? {
              ...prev,
              acceptedAnswerId: answerId,
              answers: prev.answers.map((a) => ({
                ...a,
                isAccepted: a.id === answerId,
              })),
            }
          : prev
      );
    } catch (err: any) {
      alert(err.message || "Failed to accept answer");
    }
  };

  const handleReport = async () => {
    if (!confirm("Report this question as inappropriate?")) return;
    try {
      await report(id, { reason: "Inappropriate content", type: "QUESTION" });
      setReportSuccess("Report submitted.");
      setTimeout(() => setReportSuccess(null), 3000);
    } catch (err: any) {
      alert(err.message || "Failed to report");
    }
  };

  if (loading) {
    return (
      <div className="pb-24">
        <LoadingSkeleton count={1} height="h-40" />
        <div className="mt-6 space-y-4">
          <LoadingSkeleton count={3} height="h-20" />
        </div>
      </div>
    );
  }

  if (error || !question) {
    return <ErrorMessage message={error || "Question not found"} />;
  }

  return (
    <div className="pb-24">
      <CommunityHeader title={question.title} />

      <div className="space-y-6">
        <Card>
          <CardContent className="p-5 space-y-4">
            <div className="flex items-center justify-between text-sm text-muted-foreground">
              <span>asked by {question.author.name}</span>
              <span>{new Date(question.createdAt).toLocaleDateString()}</span>
            </div>
            <div className="prose prose-sm max-w-none text-foreground">
              {question.content}
            </div>
            <div className="flex flex-wrap items-center gap-4 pt-2 border-t border-border">
              <Button size="sm" variant="outline" onClick={handleUpvote}>
                <ThumbsUp className="w-4 h-4 mr-1.5" />
                {question.upvotes}
              </Button>
              <Button size="sm" variant="ghost" onClick={handleReport}>
                <AlertCircle className="w-4 h-4 mr-1.5" />
                Report
              </Button>
              {reportSuccess && (
                <span className="text-sm text-success">{reportSuccess}</span>
              )}
            </div>
          </CardContent>
        </Card>

        <div>
          <h2 className="text-lg font-semibold text-foreground mb-4">
            Answers ({question.answers.length})
          </h2>
          {question.answers.length === 0 ? (
            <p className="text-sm text-muted-foreground">No answers yet. Be the first!</p>
          ) : (
            <div className="space-y-4">
              {question.answers.map((a) => (
                <Card
                  key={a.id}
                  className={a.isAccepted ? "border-success bg-success/5" : ""}
                >
                  <CardContent className="p-4 space-y-2">
                    <div className="flex items-center justify-between text-sm">
                      <span className="font-medium">{a.author.name}</span>
                      <span className="text-xs text-muted-foreground">
                        {new Date(a.createdAt).toLocaleDateString()}
                      </span>
                    </div>
                    <p className="text-sm">{a.content}</p>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <span>{a.upvotes} upvotes</span>
                      {a.isAccepted && (
                        <Badge variant="success" size="sm" className="gap-1">
                          <CheckCircle className="w-3 h-3" />
                          Accepted
                        </Badge>
                      )}
                      {!a.isAccepted && !question.acceptedAnswerId && (
                        <Button
                          size="xs"
                          variant="ghost"
                          onClick={() => handleAccept(a.id)}
                          className="text-success hover:bg-success/10"
                        >
                          Accept
                        </Button>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>

        <div className="flex gap-3">
          <input
            type="text"
            value={answer}
            onChange={(e) => setAnswer(e.target.value)}
            placeholder="Write your answer..."
