"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { useQuery } from "@/lib/hooks/useQuery";
import { getGroup, updateGroup } from "@/lib/api/study-groups.api";
import type { StudyGroup } from "@/types/study-groups";
import { PageHeader } from "@/components/shared/PageHeader";
import { LoadingState } from "@/components/shared/DashboardPrimitives";
import { ErrorState } from "@/components/shared/ErrorState";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

export default function EditGroupPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();

  const { data: group, loading: loadingGroup, error, refetch } = useQuery<StudyGroup>(
    () => getGroup(id),
    [id]
  );

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [isPrivate, setIsPrivate] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (group) {
      setName(group.name);
      setDescription(group.description || "");
      setIsPrivate(group.isPrivate);
    }
  }, [group]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      await updateGroup(id, { name, description, isPrivate });
      router.push(`/dashboard/study-groups/${id}`);
    } catch (err) {
      alert("Failed to update group");
    } finally {
      setSaving(false);
    }
  };

  if (loadingGroup) return <LoadingState label="Loading group" />;
  if (error) return <ErrorState title="Failed to load group" description={error.message} onRetry={refetch} />;
  if (!group) return null;

  return (
    <div className="max-w-xl mx-auto">
      <PageHeader title="Edit Group" backHref={`/dashboard/study-groups/${id}`} />

      <Card className="mt-4">
        <form onSubmit={handleSubmit} className="space-y-4">
          <Input
            label="Group Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            disabled={saving}
          />
          <Input
            label="Description (optional)"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={saving}
          />
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={isPrivate}
              onChange={(e) => setIsPrivate(e.target.checked)}
              className="h-4 w-4 text-primary rounded border-border focus:ring-primary"
              disabled={saving}
            />
            <span className="text-sm text-foreground">Private</span>
          </label>
          <div className="flex gap-2 pt-2">
            <Button variant="outline" onClick={() => router.back()} disabled={saving}>
              Cancel
            </Button>
            <Button type="submit" disabled={saving}>
              {saving ? "Saving..." : "Save"}
            </Button>
          </div>
        </form>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useQuery } from "@/lib/hooks/useQuery";
import {
  getGroup,
  deleteGroup,
  getMessages,
  sendMessage,
  listMembers,
  updateMemberRole,
  kickMember,
  listInvites,
  createInvite,
  revokeInvite,
  listChallenges,
  createChallenge,
  acceptChallenge,
  declineChallenge,
  getChallengeResult,
  shareSummary,
  askGroupQuestion,
  getQuizLeaderboard,
} from "@/lib/api/study-groups.api";
import type { StudyGroup, GroupMessage, GroupMember, GroupInvite, Challenge, QuizLeaderboardEntry } from "@/types/study-groups";
import { PageHeader } from "@/components/shared/PageHeader";
import { LoadingState, EmptyState } from "@/components/shared/DashboardPrimitives";
import { ErrorState } from "@/components/shared/ErrorState";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

// ─── Tab Component (inline, no external dependency) ──────────────────────────

interface TabItem {
  value: string;
  label: string;
  content: React.ReactNode;
}

function Tabs({ tabs, defaultTab }: { tabs: TabItem[]; defaultTab?: string }) {
  const [activeTab, setActiveTab] = useState(defaultTab || tabs[0]?.value || "");

  return (
    <div>
      <div className="flex space-x-1 border-b border-border mb-4">
        {tabs.map((tab) => (
          <button
            key={tab.value}
            onClick={() => setActiveTab(tab.value)}
            className={cn(
              "px-4 py-2 text-sm font-medium transition-colors rounded-t-lg",
              activeTab === tab.value
                ? "text-primary border-b-2 border-primary"
                : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
            )}
          >
            {tab.label}
          </button>
        ))}
      </div>
      <div>{tabs.find((t) => t.value === activeTab)?.content}</div>
    </div>
  );
}

// ─── Extracted Components (inline to avoid missing imports) ──────────────────

function MemberList({
  groupId,
  members,
  onUpdate,
}: {
  groupId: string;
  members: GroupMember[];
  onUpdate: () => void;
}) {
  const [updating, setUpdating] = useState<string | null>(null);

  const handleRoleChange = async (userId: string, role: "ADMIN" | "MODERATOR" | "MEMBER") => {
    setUpdating(userId);
    try {
      await updateMemberRole(groupId, userId, { role });
      onUpdate();
    } catch {
      alert("Failed to update role");
    } finally {
      setUpdating(null);
    }
  };

  const handleKick = async (userId: string) => {
    if (!confirm("Kick this member?")) return;
    try {
      await kickMember(groupId, userId);
      onUpdate();
    } catch {
      alert("Failed to kick member");
    }
  };

  if (members.length === 0) {
    return <p className="text-muted-foreground">No members found.</p>;
  }

  return (
    <div className="space-y-2">
      {members.map((member) => (
        <Card key={member.userId} compact className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
          <div>
            <p className="font-medium text-foreground">{member.name}</p>
            <Badge variant="outline" size="sm">{member.role}</Badge>
          </div>
          <div className="flex gap-2">
            <select
              value={member.role}
              onChange={(e) => handleRoleChange(member.userId, e.target.value as any)}
              disabled={updating === member.userId}
              className="border border-border rounded-lg px-2 py-1 text-sm bg-background"
            >
              <option value="MEMBER">Member</option>
              <option value="MODERATOR">Moderator</option>
              <option value="ADMIN">Admin</option>
            </select>
            <Button variant="destructive" size="xs" onClick={() => handleKick(member.userId)}>
              Kick
            </Button>
          </div>
        </Card>
      ))}
