"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  User,
  Mail,
  Phone,
  ChevronDown,
  CheckCircle,
  Badge,
  GraduationCap,
  Lock,
  Eye,
  EyeOff,
  Download,
} from "lucide-react";

import { authApi as apiClient, schoolApi } from "@/lib/api";
import { ProgressDots } from "@/components/shared/ProgressDots";
import { SearchInput } from "@/components/shared/SearchInput";
import {
  SelectionList,
  type SelectionItem,
} from "@/components/shared/SelectionList";
import { ErrorMessage } from "@/components/ui/ErrorMessage";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import type {
  SchoolType,
  FacultyType,
  DepartmentType,
  RegistrationFormData,
  RegistrationStep,
} from "@/types/auth";
import { Check, Circle } from "lucide-react";

export default function RegisterPage() {
  const [currentStep, setCurrentStep] = useState<RegistrationStep>("school");
  const [searchQuery, setSearchQuery] = useState("");

  // Form data
  const [selectedSchool, setSelectedSchool] = useState<SchoolType | null>(null);
  const [selectedFaculty, setSelectedFaculty] = useState<FacultyType | null>(
    null,
  );
  const [selectedDepartment, setSelectedDepartment] =
    useState<DepartmentType | null>(null);

  const [formData, setFormData] = useState<RegistrationFormData>({
    fullName: "",
    email: "",
    phone: "",
    matriculation: "",
    level: "",
    password: "",
    confirmPassword: "",
    agreeToTerms: false,
  });

  // API data states
  const [schools, setSchools] = useState<SchoolType[]>([]);
  const [faculties, setFaculties] = useState<FacultyType[]>([]);
  const [departments, setDepartments] = useState<DepartmentType[]>([]);

  // Loading and error states
  const [loadingSchools, setLoadingSchools] = useState(true);
  const [loadingFaculties, setLoadingFaculties] = useState(false);
  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [schoolError, setSchoolError] = useState<string | null>(null);
  const [facultyError, setFacultyError] = useState<string | null>(null);
  const [departmentError, setDepartmentError] = useState<string | null>(null);

  const [passwordStrength, setPasswordStrength] = useState(0);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  // Fetch schools on component mount
  useEffect(() => {
    const fetchSchools = async () => {
      setLoadingSchools(true);
      setSchoolError(null);
      try {
        const data = await schoolApi.getSchools();
        setSchools(data);
      } catch (error) {
        console.error("Error fetching schools:", error);
        setSchoolError("Failed to load schools. Please refresh the page.");
      } finally {
        setLoadingSchools(false);
      }
    };
    fetchSchools();
  }, []);

  // Fetch faculties when school is selected
  useEffect(() => {
    if (!selectedSchool) {
      setFaculties([]);
      setSelectedFaculty(null);
      setDepartments([]);
      setSelectedDepartment(null);
      return;
    }

    const fetchFaculties = async () => {
      setLoadingFaculties(true);
      setFacultyError(null);
      try {
        const data = await schoolApi.getFaculties(selectedSchool.id);
        setFaculties(data);
        setSelectedFaculty(null);
        setDepartments([]);
        setSelectedDepartment(null);
      } catch (error) {
        console.error("Error fetching faculties:", error);
        setFacultyError("Failed to load faculties. Please try again.");
      } finally {
        setLoadingFaculties(false);
      }
    };

    fetchFaculties();
  }, [selectedSchool]);

  // Fetch departments when faculty is selected
  useEffect(() => {
    if (!selectedFaculty) {
      setDepartments([]);
      setSelectedDepartment(null);
      return;
    }

    const fetchDepartments = async () => {
      setLoadingDepartments(true);
      setDepartmentError(null);
      try {
        const data = await schoolApi.getDepartments(selectedFaculty.id);
        setDepartments(data);
        setSelectedDepartment(null);
      } catch (error) {
        console.error("Error fetching departments:", error);
        setDepartmentError("Failed to load departments. Please try again.");
      } finally {
        setLoadingDepartments(false);
      }
    };

    fetchDepartments();
  }, [selectedFaculty]);

  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value, type } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]:
        type === "checkbox" ? (e.target as HTMLInputElement).checked : value,
    }));

    if (name === "password") {
      calculatePasswordStrength(value);
    }
  };

  const calculatePasswordStrength = (password: string) => {
    let strength = 0;
    if (password.length >= 8) strength++;
    if (/[A-Z]/.test(password)) strength++;
    if (/[0-9]/.test(password)) strength++;
    if (/[^A-Za-z0-9]/.test(password)) strength++;
    setPasswordStrength(strength);
  };

  const handleContinue = () => {
    if (currentStep === "school" && selectedSchool) {
      setCurrentStep("faculty");
      setSearchQuery("");
    } else if (currentStep === "faculty" && selectedFaculty) {
      setCurrentStep("department");
      setSearchQuery("");
    } else if (currentStep === "department" && selectedDepartment) {
      setCurrentStep("details");
    }
  };

  const handleBack = () => {
    if (currentStep === "details")    setCurrentStep("department");
    else if (currentStep === "department") setCurrentStep("faculty");
    else if (currentStep === "faculty")    setCurrentStep("school");
    else if (currentStep === "school")     window.location.href = "/login";
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      setSubmitError("Passwords do not match.");
      return;
    }

    setIsLoading(true);
    setSubmitError(null);
    try {
      const res = await apiClient.register({
        fullName: formData.fullName,
        email: formData.email,
        password: formData.password,
        confirmPassword: formData.confirmPassword,
        phone: formData.phone,
        matricNumber: formData.matriculation,
        level: formData.level,
        schoolId: selectedSchool?.id || "",
        facultyId: selectedFaculty?.id || "",
        departmentId: selectedDepartment?.id || "",
      });

      // Store tokens immediately so the user stays logged in after verification
      if (res?.tokens?.accessToken) {
        localStorage.setItem("auth_token", res.tokens.accessToken);
        localStorage.setItem("refresh_token", res.tokens.refreshToken);
        localStorage.setItem("auth_user", JSON.stringify(res.user));
        localStorage.setItem("dashboard_redirect", "mobile_app");
        // Sync to HTTP-only cookie so the splash auth check works
        await fetch("/api/auth/set-cookie", {
          method:  "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            accessToken: res.tokens.accessToken,
          }),
        });
      }

      window.location.href = `/verify-otp?email=${encodeURIComponent(formData.email)}&type=email-verification`;
    } catch (error: any) {
      setSubmitError(error?.message || "An error occurred. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const getStepIndex = (): number => {
    const steps: RegistrationStep[] = [
      "school",
      "faculty",
      "department",
      "details",
    ];
    return steps.indexOf(currentStep);
  };

  return (
    <div className="min-h-screen w-full bg-background flex flex-col px-4 py-6">
      {/* Header */}
      <div className="flex items-center mb-6">
        <button
          onClick={handleBack}
          className="p-2 hover:bg-muted rounded-lg transition"
        >
          <ArrowLeft className="w-6 h-6 text-foreground" />
        </button>
      </div>

      {/* Progress Indicator */}
      <ProgressDots currentStep={currentStep} />

      <div className="max-w-2xl w-full mx-auto flex-1">
        {/* School Selection */}
        {currentStep === "school" && (
          <div>
            <h1 className="text-3xl font-bold text-foreground mb-2">
              Select Your School
            </h1>
            <p className="text-muted-foreground mb-6">
              Choose the institution you're enrolled in
            </p>

            {schoolError && <ErrorMessage message={schoolError} />}

            {loadingSchools ? (
              <LoadingSkeleton />
            ) : (
              <>
                <SearchInput
                  placeholder="Search schools..."
                  value={searchQuery}
                  onChange={setSearchQuery}
                />
                <SelectionList
                  items={schools.map((school) => ({
                    id: school.id,
                    name: school.name,
                    code: school.shortCode,
                    icon: <GraduationCap className="w-8 h-8 text-primary" />,
                  }))}
                  selectedId={selectedSchool?.id || null}
                  onSelect={(id) => {
                    const school = schools.find((s) => s.id === id);
                    setSelectedSchool(school || null);
                  }}
                  filterQuery={searchQuery}
                  isLoading={false}
                />
              </>
            )}
          </div>
        )}

        {/* Faculty Selection */}
        {currentStep === "faculty" && (
          <div>
            <h1 className="text-3xl font-bold text-foreground mb-2">
              Select Your Faculty
            </h1>
            <p className="text-muted-foreground mb-6">
              Choose your faculty within {selectedSchool?.shortCode}
            </p>

            {facultyError && <ErrorMessage message={facultyError} />}

            {loadingFaculties ? (
              <LoadingSkeleton />
            ) : (
              <>
                <SearchInput
                  placeholder="Search faculties..."
                  value={searchQuery}
                  onChange={setSearchQuery}
                />
                <SelectionList
                  items={faculties.map((faculty) => ({
                    id: faculty.id,
                    name: faculty.name,
                    icon: <Download className="w-8 h-8 text-primary" />,
                  }))}
                  selectedId={selectedFaculty?.id || null}
                  onSelect={(id) => {
                    const faculty = faculties.find((f) => f.id === id);
                    setSelectedFaculty(faculty || null);
                  }}
                  filterQuery={searchQuery}
                  isLoading={false}
                />
              </>
            )}
          </div>
        )}

        {/* Department Selection */}
        {currentStep === "department" && (
          <div>
            <h1 className="text-3xl font-bold text-foreground mb-2">
              Select Your Department
            </h1>
            <p className="text-muted-foreground mb-6">
              Choose your department within {selectedFaculty?.name}
            </p>

            {departmentError && <ErrorMessage message={departmentError} />}

            {loadingDepartments ? (
              <LoadingSkeleton />
            ) : (
              <>
                <SearchInput
                  placeholder="Search departments..."
                  value={searchQuery}
                  onChange={setSearchQuery}
                />
                <SelectionList
                  items={departments.map((dept) => ({
                    id: dept.id,
                    name: dept.name,
                    code: dept.shortCode,
                    icon: <Badge className="w-8 h-8 text-primary" />,
                  }))}
                  selectedId={selectedDepartment?.id || null}
                  onSelect={(id) => {
                    const dept = departments.find((d) => d.id === id);
                    setSelectedDepartment(dept || null);
                  }}
                  filterQuery={searchQuery}
                  isLoading={false}
                />
              </>
            )}
          </div>
        )}

        {/* Personal Details */}
        {currentStep === "details" && (
          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <h1 className="text-3xl font-bold text-foreground mb-2">
                Complete Your Profile
              </h1>
              <p className="text-muted-foreground mb-6">
                Fill in your personal details
              </p>
            </div>

            {/* Full Name */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Full Name
              </label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="text"
                  name="fullName"
                  placeholder="John Doe"
                  value={formData.fullName}
                  onChange={handleInputChange}
                  autoComplete="name"
                  required
                  className="w-full pl-12 pr-4 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
              </div>
            </div>

            {/* Email */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="email"
                  name="email"
                  placeholder="john@example.com"
                  value={formData.email}
                  onChange={handleInputChange}
                  autoComplete="email"
                  required
                  className="w-full pl-12 pr-4 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
              </div>
            </div>

            {/* Phone */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Phone Number
              </label>
              <div className="flex gap-2">
                <div className="relative shrink-0 w-24">
                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                  <input
                    type="text"
                    defaultValue="+234"
                    disabled
                    className="w-full pl-10 pr-2 py-3 rounded-lg border border-border bg-muted text-muted-foreground font-semibold focus:outline-none"
                  />
                </div>
                <input
                  type="tel"
                  name="phone"
                  placeholder="8012345678"
                  value={formData.phone}
                  onChange={handleInputChange}
                  autoComplete="tel"
                  required
                  className="flex-1 px-4 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
              </div>
            </div>

            {/* Matriculation */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Matriculation Number
              </label>
              <div className="relative">
                <Badge className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="text"
                  name="matriculation"
                  placeholder="CSC/2021/001"
                  value={formData.matriculation}
                  onChange={handleInputChange}
                  autoComplete="off"
                  required
                  className="w-full pl-12 pr-4 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
              </div>
            </div>

            {/* Level */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Current Level
              </label>
              <div className="relative">
                <GraduationCap className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground pointer-events-none" />
                <select
                  name="level"
                  value={formData.level}
                  onChange={handleInputChange}
                  required
                  className="w-full pl-12 pr-10 py-3 rounded-lg border border-border bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary appearance-none"
                >
                  <option value="">Select Level</option>
                  <option value="100">100</option>
                  <option value="200">200</option>
                  <option value="300">300</option>
                  <option value="400">400</option>
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground pointer-events-none" />
              </div>
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Password
              </label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  placeholder="Create a strong password"
                  value={formData.password}
                  onChange={handleInputChange}
                  autoComplete="new-password"
                  required
                  className="w-full pl-12 pr-12 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                >
                  {showPassword ? (
                    <Eye className="w-5 h-5" />
                  ) : (
                    <EyeOff className="w-5 h-5" />
                  )}
                </button>
              </div>
              {/* Password Strength Indicator */}
              {formData.password && (
                <div className="mt-2 flex gap-1">
                  {[0, 1, 2, 3].map((index) => (
                    <div
                      key={index}
                      className={`h-1 flex-1 rounded-full ${
                        index < passwordStrength
                          ? "bg-primary"
                          : "bg-muted"
                      }`}
                    />
                  ))}
                </div>
              )}
            </div>
            {/* Password Requirements Checklist (always visible) */}
            <div className="mt-3 space-y-1.5">
              {[
                { key: "length", label: "At least 8 characters", check: formData.password.length >= 8 },
                { key: "case", label: "Uppercase and lowercase letters", check: /[a-z]/.test(formData.password) && /[A-Z]/.test(formData.password) },
                { key: "number", label: "At least one number", check: /[0-9]/.test(formData.password) },
                { key: "special", label: "At least one special character", check: /[^A-Za-z0-9]/.test(formData.password) },
              ].map(({ key, label, check }) => (
                <div key={key} className="flex items-center gap-2">
                  {check
                    ? <Check className="w-4 h-4 text-success shrink-0" />
                    : <Circle className="w-4 h-4 text-muted shrink-0" />
                  }
                  <span className={`text-sm ${check ? "text-muted-foreground" : "text-muted-foreground/60"}`}>
                    {label}
                  </span>
                </div>
              ))}
            </div>

            {/* Confirm Password */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Confirm Password
              </label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <input
                  type="password"
                  name="confirmPassword"
                  placeholder="Re-enter password"
                  value={formData.confirmPassword}
                  onChange={handleInputChange}
                  autoComplete="new-password"
                  required
                  className="w-full pl-12 pr-12 py-3 rounded-lg border border-border bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
                />
                {formData.confirmPassword &&
                  formData.password === formData.confirmPassword && (
                    <CheckCircle className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-success" />
                  )}
              </div>
            </div>

            {/* Terms Checkbox */}
            <div className="flex items-start gap-3 pt-2">
              <input
                type="checkbox"
                name="agreeToTerms"
                checked={formData.agreeToTerms}
                onChange={handleInputChange}
                required
                className="w-5 h-5 rounded border-2 border-primary bg-primary accent-primary cursor-pointer mt-1"
              />
              <label className="text-sm text-foreground">
                I agree to the{" "}
                <Link
                  href="/terms"
                  className="text-primary hover:text-primary/80 font-medium"
                >
                  Terms of Service
                </Link>{" "}
                and{" "}
                <Link
                  href="/privacy"
                  className="text-primary hover:text-primary/80 font-medium"
                >
                  Privacy Policy
                </Link>
              </label>
            </div>

            {/* Create Account Button */}
            {submitError && <ErrorMessage message={submitError} />}
            <button
              type="submit"
              disabled={isLoading || !formData.agreeToTerms}
              className="w-full py-3 px-4 bg-primary text-primary-foreground text-lg font-semibold rounded-lg hover:bg-primary/90 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg mt-6"
            >
              {isLoading ? "Creating Account..." : "Create Account"}
            </button>
          </form>
        )}
      </div>

      {/* Footer with Continue Button */}
      {currentStep !== "details" && (
        <div className="max-w-2xl w-full mx-auto mt-8">
          <button
            onClick={handleContinue}
            disabled={
              (currentStep === "school" && !selectedSchool) ||
              (currentStep === "faculty" && !selectedFaculty) ||
              (currentStep === "department" && !selectedDepartment)
            }
            className="w-full py-3 px-4 bg-primary text-primary-foreground text-lg font-semibold rounded-lg hover:bg-primary/90 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg"
          >
            Continue
          </button>
        </div>
      )}

      {/* Sign In Link */}
      {currentStep === "school" && (
        <div className="text-center mt-6">
          <p className="text-muted-foreground">
            Already have an account?{" "}
            <Link
              href="/login"
              className="font-semibold text-primary hover:text-primary/80"
            >
              Sign In
            </Link>
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useMemo, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { ChevronLeft, Lock, Eye, EyeOff, Check, Circle, AlertTriangle } from "lucide-react";
import { authApi } from "@/lib/api/auth";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

function ResetPasswordPageContent() {
  const router      = useRouter();
  const searchParams = useSearchParams();

  const email = searchParams.get("email") ?? "";
  const otp   = searchParams.get("otp")   ?? "";

  const [password, setPassword]         = useState("");
  const [confirm, setConfirm]           = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm]   = useState(false);
  const [isLoading, setIsLoading]       = useState(false);
  const [error, setError]               = useState<string | null>(null);

  const missingParams = !email || !otp;

  const checks = useMemo(
    () => ({
      length:  password.length >= 8,
      case:    /[a-z]/.test(password) && /[A-Z]/.test(password),
      number:  /[0-9]/.test(password),
      special: /[^A-Za-z0-9]/.test(password),
    }),
    [password],
  );

  const score = Object.values(checks).filter(Boolean).length;
  const strengthLabel = ["Weak", "Fair", "Good", "Strong"][Math.max(score - 1, 0)] || "Weak";
  const strengthColor =
    score <= 1 ? "bg-destructive" :
    score <= 3 ? "bg-warning" :
                 "bg-success";

  const isValid = score === 4 && password === confirm && password.length > 0;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isValid || missingParams) return;

    setError(null);
    setIsLoading(true);

    try {
      await authApi.resetPassword({ email, otp, password, confirmPassword: confirm });
      router.push("/login?reset=success");
    } catch (err: any) {
      setError(err?.message || "Failed to reset password. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  if (missingParams) {
    return (
      <div className="min-h-screen w-full bg-background px-6 py-8 flex flex-col items-center justify-center gap-5">
        <Card className="max-w-sm w-full p-6 text-center">
          <div className="w-16 h-16 rounded-lg bg-destructive/10 flex items-center justify-center mx-auto mb-4">
            <AlertTriangle className="w-7 h-7 text-destructive" />
          </div>
          <h1 className="text-xl font-bold text-foreground mb-2">Invalid Reset Link</h1>
          <p className="text-muted-foreground text-sm max-w-xs mx-auto">
            This password reset link is missing, invalid, or has expired.
          </p>
          <div className="mt-6">
            <Button
              onClick={() => router.push("/forgot-password")}
              className="w-full"
            >
              Request New Reset
            </Button>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen w-full bg-background px-6 py-8 flex flex-col">
      <button
        onClick={() => router.back()}
        className="text-foreground mb-16"
        aria-label="Go back"
      >
        <ChevronLeft className="w-6 h-6" />
      </button>

      <div className="flex flex-col items-center text-center mb-8">
        <div className="w-16 h-16 rounded-lg bg-primary/10 flex items-center justify-center mb-6">
          <Lock className="w-7 h-7 text-primary" />
        </div>
        <h1 className="text-2xl font-bold text-foreground mb-2">
          Create New Password
        </h1>
        <p className="text-muted-foreground">Enter a new password for</p>
        <p className="text-foreground font-semibold text-sm mt-0.5">{email}</p>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-4" noValidate>
        <div className="relative">
          <Lock className="w-5 h-5 text-muted-foreground absolute left-4 top-1/2 -translate-y-1/2" />
          <input
            type={showPassword ? "text" : "password"}
            value={password}
            onChange={(e) => { setPassword(e.target.value); setError(null); }}
            placeholder="New password"
            autoComplete="new-password"
            disabled={isLoading}
            className="w-full rounded-lg bg-muted border border-border pl-12 pr-12 py-4 text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary disabled:opacity-60"
          />
          <button
            type="button"
            onClick={() => setShowPassword(v => !v)}
            className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition"
            aria-label={showPassword ? "Hide password" : "Show password"}
          >
            {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
          </button>
        </div>

        <div className="relative">
          <Lock className="w-5 h-5 text-muted-foreground absolute left-4 top-1/2 -translate-y-1/2" />
          <input
            type={showConfirm ? "text" : "password"}
            value={confirm}
            onChange={(e) => { setConfirm(e.target.value); setError(null); }}
            placeholder="Confirm password"
            autoComplete="new-password"
            disabled={isLoading}
            className="w-full rounded-lg bg-muted border border-border pl-12 pr-12 py-4 text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary disabled:opacity-60"
          />
          <button
            type="button"
            onClick={() => setShowConfirm(v => !v)}
            className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition"
            aria-label={showConfirm ? "Hide confirm password" : "Show confirm password"}
          >
            {showConfirm ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
          </button>
        </div>

        {confirm.length > 0 && password !== confirm && (
          <p className="text-sm text-destructive -mt-2">Passwords do not match.</p>
        )}

        {password.length > 0 && (
          <div>
            <div className="flex gap-1.5 mb-2">
              {[0, 1, 2, 3].map(i => (
                <span
                  key={i}
                  className={`h-1.5 flex-1 rounded-full transition-colors ${
                    i < score
                      ? score <= 1 ? 'bg-destructive' :
                        score <= 3 ? 'bg-warning' :
                        'bg-success'
                      : 'bg-muted'
                  }`}
                />
              ))}
            </div>
            <p className="text-sm font-medium text-muted-foreground mb-3">{strengthLabel}</p>

            <div className="flex flex-col gap-1.5">
              {[
                { key: "length"  as const, label: "At least 8 characters" },
                { key: "case"    as const, label: "Uppercase and lowercase letters" },
                { key: "number"  as const, label: "At least one number" },
                { key: "special" as const, label: "At least one special character" },
              ].map(({ key, label }) => (
                <div key={key} className="flex items-center gap-2">
                  {checks[key]
                    ? <Check className="w-4 h-4 text-success shrink-0" />
                    : <Circle className="w-4 h-4 text-muted shrink-0" />
                  }
                  <span className={`text-sm ${checks[key] ? "text-muted-foreground" : "text-muted-foreground/60"}`}>
                    {label}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {error && (
          <p className="text-sm text-destructive text-center">{error}</p>
        )}

        <button
          type="submit"
          disabled={!isValid || isLoading}
          className="w-full rounded-lg bg-primary py-4 text-primary-foreground font-semibold shadow-md hover:shadow-lg hover:bg-primary/90 mt-2 disabled:opacity-60 disabled:cursor-not-allowed transition"
        >
          {isLoading ? "Resetting…" : "Reset Password"}
        </button>
      </form>
    </div>
  );
}

export default function ResetPasswordPage() {
  return (
    <Suspense fallback={null}>
      <ResetPasswordPageContent />
    </Suspense>
  );
}

