"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { apiPost } from "@/lib/api";

export default function UploadMaterialPage() {
  const router = useRouter();
  const [mode, setMode] = useState<"single" | "bulk">("single");
  const [error, setError] = useState<string | null>(null);

  // Single upload state
  const [file, setFile] = useState<File | null>(null);
  const [title, setTitle] = useState("");
  const [courseCode, setCourseCode] = useState("");
  const [courseTitle, setCourseTitle] = useState("");
  const [description, setDescription] = useState("");
  const [visibility, setVisibility] = useState<"PUBLIC" | "PRIVATE" | "LINK_ONLY">("PUBLIC");

  // Bulk upload state
  const [bulkFiles, setBulkFiles] = useState<File[]>([]);
  const [bulkJson, setBulkJson] = useState("");

  const handleSingle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return setError("File required");
    const formData = new FormData();
    formData.append("file", file);
    formData.append("title", title);
    formData.append("visibility", visibility);
    if (courseCode) formData.append("courseCode", courseCode);
    if (courseTitle) formData.append("courseTitle", courseTitle);
    if (description) formData.append("description", description);
    try {
      await apiPost("/study/materials", formData, true);
      router.push("/study/materials");
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleBulk = async () => {
    if (bulkFiles.length === 0) return setError("Select files");
    let materials;
    try {
      materials = JSON.parse(bulkJson || "[]");
    } catch {
      return setError("Invalid JSON for materials");
    }
    if (!Array.isArray(materials) || materials.length !== bulkFiles.length) {
      return setError("Materials array length must match number of files");
    }
    const formData = new FormData();
    bulkFiles.forEach((f) => formData.append("files", f));
    formData.append("materials", JSON.stringify(materials));
    try {
      await apiPost("/study/materials/bulk", formData, true);
      router.push("/study/materials");
    } catch (err: any) {
      setError(err.message);
    }
  };

  return (
    <div>
      <h1 className="text-2xl font-bold mb-4">Upload Material</h1>
      <div className="flex space-x-4 mb-6">
        <button
          onClick={() => setMode("single")}
          className={`px-4 py-2 rounded ${mode === "single" ? "bg-primary text-primary-foreground" : "bg-secondary/50"}`}
        >
          Single Upload
        </button>
        <button
          onClick={() => setMode("bulk")}
          className={`px-4 py-2 rounded ${mode === "bulk" ? "bg-primary text-primary-foreground" : "bg-secondary/50"}`}
        >
          Bulk Upload
        </button>
      </div>

      {error && (
        <div className="mb-4 bg-red-100 text-red-700 p-3 rounded">
          {error}
          <button onClick={() => setError(null)} className="ml-2 font-bold">×</button>
        </div>
      )}

      {mode === "single" ? (
        <form onSubmit={handleSingle} className="bg-card shadow rounded p-6 space-y-4 max-w-xl">
          <input type="file" onChange={e => setFile(e.target.files?.[0] || null)} required />
          <input
            type="text" placeholder="Title" value={title} onChange={e => setTitle(e.target.value)}
            className="border p-2 w-full" required
          />
          <input
            type="text" placeholder="Course Code" value={courseCode}
            onChange={e => setCourseCode(e.target.value)} className="border p-2 w-full"
          />
          <input
            type="text" placeholder="Course Title" value={courseTitle}
            onChange={e => setCourseTitle(e.target.value)} className="border p-2 w-full"
          />
          <textarea
            placeholder="Description" value={description}
            onChange={e => setDescription(e.target.value)} className="border p-2 w-full"
          />
          <select value={visibility} onChange={e => setVisibility(e.target.value as any)} className="border p-2 w-full">
            <option value="PUBLIC">Public</option>
            <option value="PRIVATE">Private</option>
            <option value="LINK_ONLY">Link Only</option>
          </select>
          <button type="submit" className="bg-primary text-primary-foreground px-6 py-2 rounded">
            Upload
          </button>
        </form>
      ) : (
        <div className="bg-card shadow rounded p-6 max-w-xl space-y-4">
          <input type="file" multiple onChange={e => setBulkFiles(Array.from(e.target.files || []))} />
          <textarea
            placeholder='[{"title":"...","visibility":"PUBLIC"}]' value={bulkJson}
            onChange={e => setBulkJson(e.target.value)} className="border p-2 w-full" rows={6}
          />
          <button onClick={handleBulk} className="bg-success text-primary-foreground px-6 py-2 rounded">
            Bulk Upload
          </button>
        </div>
      )}
    </div>
  );
}

// app/study/personal/[sessionId]/page.tsx
"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { apiGet, apiPost } from "@/lib/api";
import type { PersonalStudyMessage, PersonalQuiz, PersonalQuizResult } from "@/types/study";

export default function SessionDetailPage() {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [session, setSession] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Chat state
  const [messages, setMessages] = useState<PersonalStudyMessage[]>([]);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);

  // Quiz state
  const [quiz, setQuiz] = useState<PersonalQuiz | null>(null);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [quizResult, setQuizResult] = useState<PersonalQuizResult | null>(null);
  const [quizTopic, setQuizTopic] = useState("");
  const [numQuestions, setNumQuestions] = useState(5);

  useEffect(() => {
    apiGet(`/personal-study/sessions/${sessionId}`).then((data) => {
      setSession(data);
      if (data.messages) setMessages(data.messages);
      setLoading(false);
    });
  }, [sessionId]);

  const handleAsk = async () => {
    if (!input.trim()) return;
    const userMsg: PersonalStudyMessage = { role: "user", content: input };
    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setSending(true);
    try {
      const res = await apiPost(`/personal-study/sessions/${sessionId}/ask`, { question: input });
      const assistantMsg: PersonalStudyMessage = { role: "assistant", content: res.answer || res.response };
      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err: any) {
      setMessages((prev) => [...prev, { role: "assistant", content: "Error: " + err.message }]);
    }
    setSending(false);
  };

  const generateQuiz = async () => {
    try {
      const res = await apiPost(`/personal-study/sessions/${sessionId}/quiz`, {
        numQuestions,
        topic: quizTopic || undefined,
      });
      setQuiz(res);
      setAnswers({});
      setQuizResult(null);
    } catch (err: any) {
      alert("Failed to generate quiz: " + err.message);
    }
  };

  const submitQuiz = async () => {
    if (!quiz) return;
    const payload = {
      answers: quiz.questions.map((q) => ({
        questionId: q.id,
        selected: answers[q.id] ?? 0,
      })),
    };
    try {
      const res = await apiPost(`/personal-study/sessions/${sessionId}/quiz/submit`, payload);
      setQuizResult(res);
    } catch (err: any) {
      alert("Error submitting quiz: " + err.message);
    }
  };

  if (loading) return <p>Loading session...</p>;
  if (!session) return <p>Session not found.</p>;

  return (
    <div className="max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-2">{session.title}</h1>
      <p className="text-muted-foreground mb-6">Session ID: {sessionId}</p>

      {/* Chat Section */}
      <div className="bg-card shadow rounded p-4 mb-6">
        <h2 className="text-lg font-semibold mb-2">Ask a Question</h2>
        <div className="h-64 overflow-y-auto border p-3 rounded mb-2 space-y-2">
          {messages.map((msg, i) => (
            <div key={i} className={`p-2 rounded ${msg.role === "user" ? "bg-primary/5 ml-8" : "bg-muted/80 mr-8"}`}>
              <strong>{msg.role === "user" ? "You" : "AI"}:</strong> {msg.content}
            </div>
          ))}
          {sending && <div className="text-muted-foreground/70">Thinking...</div>}
        </div>
        <div className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleAsk()}
            placeholder="Ask about the material..."
            className="border p-2 flex-1"
          />
          <button onClick={handleAsk} className="bg-primary text-primary-foreground px-4 py-2 rounded">
            Send
          </button>
        </div>
      </div>

      {/* Quiz Section */}
      <div className="bg-card shadow rounded p-4">
        <h2 className="text-lg font-semibold mb-2">Generate a Quiz</h2>
        <div className="flex gap-2 mb-4">
          <input
            type="text"
            placeholder="Topic (optional)"
            value={quizTopic}
            onChange={(e) => setQuizTopic(e.target.value)}
            className="border p-2 w-48"
          />
          <input
            type="number"
            min={1}
            max={10}
            value={numQuestions}
            onChange={(e) => setNumQuestions(Number(e.target.value))}
            className="border p-2 w-20"
          />
          <button onClick={generateQuiz} className="bg-primary text-primary-foreground px-4 py-2 rounded">
            Generate
          </button>
        </div>

        {quiz && !quizResult && (
          <div>
            {quiz.questions.map((q, idx) => (
              <div key={q.id} className="mb-4">
                <p className="font-medium">{idx + 1}. {q.text}</p>
                {q.options.map((opt, oi) => {
                  const optText = typeof opt === "string" ? opt : opt.text;
                  return (
                    <label key={oi} className="block ml-4">
                      <input
                        type="radio"
                        name={q.id}
                        value={oi}
                        checked={answers[q.id] === oi}
                        onChange={() => setAnswers((prev) => ({ ...prev, [q.id]: oi }))}
                        className="mr-2"
                      />
                      {optText}
                    </label>
                  );
                })}
              </div>
            ))}
            <button onClick={submitQuiz} className="bg-success text-primary-foreground px-4 py-2 rounded">
              Submit Answers
            </button>
          </div>
        )}

        {quizResult && (
          <div className="bg-success/5 p-4 rounded">
            <p className="font-bold">Score: {quizResult.score} / {quizResult.total}</p>
            <button onClick={() => { setQuiz(null); setQuizResult(null); }} className="mt-2 text-primary underline">
              Take Another Quiz
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

