// app/study/materials/page.tsx
"use client";

import { useState, useEffect, useCallback } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { apiGet } from "@/lib/api";
import { Search, Filter, Download, Eye, BookOpen, Globe, Lock, Plus, ChevronLeft, ChevronRight } from "lucide-react";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type { Material } from "@/types/study";

export default function MaterialsListPage() {
  const router = useRouter();
  const [materials, setMaterials] = useState<Material[]>([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [courseFilter, setCourseFilter] = useState("");
  const limit = 12;

  const fetchMaterials = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const params = new URLSearchParams();
      params.set("page", String(page));
      params.set("limit", String(limit));
      if (search) params.set("search", search);
      if (courseFilter) params.set("course", courseFilter);
      const data = await apiGet(`/study/materials?${params.toString()}`);
      setMaterials(data.data || data || []);
      setTotal(data.total || 0);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [page, search, courseFilter]);

  useEffect(() => {
    fetchMaterials();
  }, [fetchMaterials]);

  const totalPages = Math.ceil(total / limit);

  const visibilityIcon = (visibility: string) => {
    if (visibility === "PUBLIC") return <Globe className="w-4 h-4 text-success" />;
    return <Lock className="w-4 h-4 text-muted-foreground" />;
  };

  if (loading && page === 1) {
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold">Study Materials</h1>
          <Link href="/study/materials/upload">
            <Button>Upload New</Button>
          </Link>
        </div>
        <LoadingSkeleton count={6} height="h-40" radius="rounded-2xl" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-destructive/5 border border-destructive/20 rounded-xl p-6 text-destructive">
        <p>Failed to load materials: {error}</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Study Materials</h1>
          <p className="text-muted-foreground text-sm">
            {total > 0 ? `Showing ${(page - 1) * limit + 1}–${Math.min(page * limit, total)} of ${total} materials` : "No materials yet"}
          </p>
        </div>
        <Link href="/study/materials/upload">
          <Button>
            <Plus className="w-4 h-4 mr-2" />
            Upload New
          </Button>
        </Link>
      </div>

      {/* Search & Filter */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search materials..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <Input
          type="text"
          placeholder="Filter by course code"
          value={courseFilter}
          onChange={(e) => setCourseFilter(e.target.value)}
          className="sm:w-48"
        />
      </div>

      {/* Materials Grid */}
      {materials.length === 0 ? (
        <div className="bg-card rounded-2xl border border-dashed p-12 text-center">
          <BookOpen className="w-12 h-12 text-muted-foreground/50 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-foreground">No materials found</h3>
          <p className="text-muted-foreground">Try adjusting your search or upload a new material.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {materials.map((mat) => (
            <Link
              key={mat.id}
              href={`/study/materials/${mat.id}`}
              className="block bg-card rounded-2xl border border-border hover:shadow-md transition-all hover:border-primary/50 group"
            >
              <div className="p-5">
                <div className="flex items-start justify-between mb-3">
                  <div className="p-2 rounded-lg bg-primary/10 text-primary group-hover:bg-primary/20 transition">
                    <BookOpen className="w-5 h-5" />
                  </div>
                  <div className="flex items-center gap-1 text-xs">
                    {visibilityIcon(mat.visibility)}
                    <span className="text-muted-foreground">{mat.visibility}</span>
                  </div>
                </div>
                <h3 className="font-semibold text-foreground line-clamp-2 group-hover:text-primary transition">
                  {mat.title}
                </h3>
                {mat.courseCode && (
                  <p className="text-sm text-muted-foreground mt-1">{mat.courseCode}</p>
                )}
                {mat.description && (
                  <p className="text-sm text-muted-foreground line-clamp-2 mt-2">{mat.description}</p>
                )}
                <div className="flex items-center gap-3 mt-4 pt-3 border-t border-border text-xs text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <Download className="w-3.5 h-3.5" />
                    {mat.downloads || 0}
                  </span>
                  <span className="flex items-center gap-1">
                    <Eye className="w-3.5 h-3.5" />
                    View
                  </span>
                  {mat.averageRating && (
                    <span className="flex items-center gap-1">
                      <span>⭐</span>
                      {mat.averageRating.toFixed(1)}
                    </span>
                  )}
                </div>
              </div>
            </Link>
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex justify-between items-center pt-4 border-t border-border">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
          >
            <ChevronLeft className="w-4 h-4 mr-1" />
            Previous
          </Button>
          <span className="text-sm text-muted-foreground">
            Page {page} of {totalPages}
          </span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
          >
            Next
            <ChevronRight className="w-4 h-4 ml-1" />
          </Button>
        </div>
      )}
    </div>
  );
}

import * as React from "react";
// app/study/materials/upload/page.tsx
"use client";

import { useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { apiPost } from "@/lib/api";
import { Upload, File, X, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card } from "@/components/ui/card";
import type { MaterialVisibility } from "@/types/study";

export default function UploadMaterialPage() {
  const router = useRouter();
  const [mode, setMode] = useState<"single" | "bulk">("single");
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  // Single upload
  const [file, setFile] = useState<File | null>(null);
  const [title, setTitle] = useState("");
  const [courseCode, setCourseCode] = useState("");
  const [courseTitle, setCourseTitle] = useState("");
  const [description, setDescription] = useState("");
  const [visibility, setVisibility] = useState<MaterialVisibility>("PUBLIC");

  // Bulk upload
  const [bulkFiles, setBulkFiles] = useState<File[]>([]);
  const [bulkJson, setBulkJson] = useState("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSingle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return setError("Please select a file");
    setUploading(true);
    setError(null);
    const formData = new FormData();
    formData.append("file", file);
    formData.append("title", title);
    formData.append("visibility", visibility);
    if (courseCode) formData.append("courseCode", courseCode);
    if (courseTitle) formData.append("courseTitle", courseTitle);
    if (description) formData.append("description", description);
    try {
      await apiPost("/study/materials", formData, true);
      router.push("/study/materials");
    } catch (err: any) {
      setError(err.message);
    } finally {
      setUploading(false);
    }
  };

  const handleBulk = async () => {
    if (bulkFiles.length === 0) return setError("Select at least one file");
    let materials;
    try {
      materials = JSON.parse(bulkJson || "[]");
    } catch {
      return setError("Invalid JSON");
    }
    if (!Array.isArray(materials) || materials.length !== bulkFiles.length) {
      return setError("Number of files must match number of material objects");
    }
    setUploading(true);
    const formData = new FormData();
    bulkFiles.forEach((f) => formData.append("files", f));
    formData.append("materials", JSON.stringify(materials));
    try {
      await apiPost("/study/materials/bulk", formData, true);
      router.push("/study/materials");
    } catch (err: any) {
      setError(err.message);
    } finally {
      setUploading(false);
    }
  };

  const removeBulkFile = (index: number) => {
    setBulkFiles(files => files.filter((_, i) => i !== index));
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div>
        <h1 className="text-2xl font-bold">Upload Material</h1>
        <p className="text-muted-foreground">Share your study resources with the community</p>
      </div>

      {/* Mode toggle */}
      <div className="flex gap-3 bg-muted/50 rounded-xl p-1">
        <button
          onClick={() => setMode("single")}
          className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition ${
            mode === "single" ? "bg-card shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"
          }`}
        >
          Single Upload
        </button>
        <button
          onClick={() => setMode("bulk")}
          className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition ${
            mode === "bulk" ? "bg-card shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"
          }`}
        >
          Bulk Upload
        </button>
      </div>

      {error && (
        <div className="bg-destructive/5 border border-destructive/20 rounded-xl p-4 text-destructive text-sm">
          {error}
        </div>
      )}

      {mode === "single" ? (
        <form onSubmit={handleSingle} className="bg-card rounded-2xl border border-border p-6 space-y-4">
          <div>
            <Label htmlFor="file">File *</Label>
            <div className="mt-1 flex items-center gap-3">
              <Input
                id="file"
                type="file"
                ref={fileInputRef}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFile(e.target.files?.[0] || null)}
                className="flex-1"
              />
              {file && (
                <span className="text-sm text-muted-foreground truncate max-w-xs">{file.name}</span>
              )}
            </div>
          </div>
          <div>
            <Label htmlFor="title">Title *</Label>
            <Input id="title" value={title} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setTitle(e.target.value)} required />
          </div>
          <div>
            <Label htmlFor="courseCode">Course Code</Label>
            <Input id="courseCode" value={courseCode} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCourseCode(e.target.value)} />
          </div>
          <div>
            <Label htmlFor="courseTitle">Course Title</Label>
            <Input id="courseTitle" value={courseTitle} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCourseTitle(e.target.value)} />
          </div>
          <div>
            <Label htmlFor="description">Description</Label>
            <Textarea id="description" value={description} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setDescription(e.target.value)} rows={3} />
          </div>
          <div>
            <Label htmlFor="visibility">Visibility</Label>
            <Select value={visibility} onValueChange={(val) => setVisibility(val as MaterialVisibility)}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="PUBLIC">Public</SelectItem>
                <SelectItem value="PRIVATE">Private</SelectItem>
                <SelectItem value="LINK_ONLY">Link Only</SelectItem>
                <SelectItem value="DEPARTMENT">Department</SelectItem>
                <SelectItem value="LEVEL">Level</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <Button type="submit" disabled={uploading} className="w-full sm:w-auto">
            {uploading ? "Uploading..." : "Upload"}
          </Button>
        </form>
      ) : (
        <div className="bg-card rounded-2xl border border-border p-6 space-y-4">
          <div>
            <Label>Select Files *</Label>
            <Input
              type="file"
              multiple
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                const files = Array.from(e.target.files ?? []);
                setBulkFiles(prev => [...prev, ...files]);
              }}
              className="mt-1"
            />
            {bulkFiles.length > 0 && (
              <div className="mt-3 space-y-2">
                {bulkFiles.map((f, i) => (
                  <div key={i} className="flex items-center justify-between bg-muted/50 rounded-lg px-3 py-2 text-sm">
                    <span className="truncate">{f.name}</span>
                    <button type="button" onClick={() => removeBulkFile(i)} className="text-destructive hover:text-destructive/80">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div>
            <Label htmlFor="bulkJson">Materials JSON (array of objects)</Label>
            <Textarea
              id="bulkJson"
              placeholder='[{"title":"Math Notes","visibility":"PUBLIC"}]'
              value={bulkJson}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBulkJson(e.target.value)}
              rows={5}
              className="mt-1 font-mono text-sm"
            />
          </div>
          <Button onClick={handleBulk} disabled={uploading || bulkFiles.length === 0}>
            {uploading ? "Uploading..." : "Upload All"}
          </Button>
        </div>
      )}
    </div>
  );
}

