import { MapPin } from "lucide-react";
"use client";

import { useEffect, useCallback, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { AlertCircle, Loader2 } from "lucide-react";
import { useMapStore } from "@/lib/map/state/store";
import {
  mapLocationService,
  mapEntranceService,
  mapRoutingService,
  mapCategoryService,
  mapConfigService,
} from "@/lib/map/services";
import { useGPSTracking } from "@/lib/map/hooks";
import { isMapLocation } from "@/lib/map/utils";
import { LocationType } from "@/lib/map/types/location";
import MapCanvas from "./MapCanvas";
import { MapHeader } from "./MapHeader";
import { LocationPanel } from "./LocationPanel";
import NavigationPanel from "./NavigationPanel";
import { FloatingControls } from "./FloatingControls";
import { GPSPermissionModal } from "./GPSPermissionModal";
import { GPSPermissionBanner } from "./GPSPermissionBanner";

export default function MapContainer() {
  const router = useRouter();
  const initRef = useRef(false);

  // GPS tracking
  const {
    position: gpsPosition,
    isTracking,
    permissionState: gpsPermissionState,
    error: gpsError,
    requestPermission: requestGPSPermission,
    startTracking,
    stopTracking,
  } = useGPSTracking(true, 10000, 0);

  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [showPermissionBanner, setShowPermissionBanner] = useState(false);
  const [isRequestingPermission, setIsRequestingPermission] = useState(false);

  // Zustand store
  const {
    camera,
    setCamera,
    animateToCamera,
    resetCamera,
    locations,
    filteredLocations,
    selectedLocation,
    setLocations,
    setFilteredLocations,
    setSelectedLocation,
    setSelectedEntrance,
    clearSelection,
    activeFilter,
    setActiveFilter,
    searchQuery,
    setSearchQuery,
    isLoading,
    setIsLoading,
    error,
    setError,
    clearError,
    viewMode,
    setViewMode,
    showLocationPanel,
    setShowLocationPanel,
    isCompactMode,
    setIsCompactMode,
    position: userPosition,
    setPosition: setUserPosition,
    isFollowing,
    setIsFollowing,
    setLocationPermission,
    currentRoute,
    setCurrentRoute,
    isNavigating,
    setIsNavigating,
    navigationError,
    setNavigationError,
  } = useMapStore();

  // ─── Initialization ───────────────────────────────────────────────

  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    const initialize = async () => {
      try {
        setIsLoading(true);
        setError(null);

        if (gpsPermissionState === "unknown" || gpsPermissionState === "prompt") {
          setShowPermissionModal(true);
        } else if (gpsPermissionState === "denied") {
          setShowPermissionBanner(true);
        }

        const [config, categories] = await Promise.all([
          mapConfigService.getMapConfig(),
          mapCategoryService.getCategories(),
        ]);

        resetCamera({
          center: config.defaultCenter,
          zoom: config.defaultZoom,
          pitch: config.defaultPitch,
          bearing: config.defaultBearing,
        });

        const initialLocations = await mapLocationService.getLocations();
        setLocations(initialLocations);
        setFilteredLocations(initialLocations);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to initialize map");
      } finally {
        setIsLoading(false);
      }
    };

    initialize();
  }, []);

  // ─── GPS sync ────────────────────────────────────────────────────

  useEffect(() => {
    if (gpsPosition) setUserPosition(gpsPosition);
  }, [gpsPosition, setUserPosition]);

  useEffect(() => {
    setLocationPermission(gpsPermissionState);
  }, [gpsPermissionState, setLocationPermission]);

  const handleRequestPermission = useCallback(async () => {
    setIsRequestingPermission(true);
    try {
      await requestGPSPermission();
    } catch (err) {
      console.error(err);
    } finally {
      setIsRequestingPermission(false);
    }
  }, [requestGPSPermission]);

  useEffect(() => {
    if (gpsPermissionState === "granted") {
      setShowPermissionModal(false);
      setShowPermissionBanner(false);
    }
  }, [gpsPermissionState]);

  // ─── Search & Filter ──────────────────────────────────────────────

  const handleSearch = useCallback(
    async (query: string) => {
      setSearchQuery(query);
      if (!query.trim()) {
        const filtered =
          activeFilter === "ALL"
            ? locations
            : locations.filter((loc) => loc.type === activeFilter);
        setFilteredLocations(filtered);
        return;
      }
      try {
        setIsLoading(true);
        const results = await mapLocationService.searchLocations({
          query,
          category: activeFilter === "ALL" ? undefined : activeFilter,
          userLocation: userPosition || undefined,
          limit: 50,
        });
        setFilteredLocations(results);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Search failed");
        setFilteredLocations([]);
      } finally {
        setIsLoading(false);
      }
    },
    [setSearchQuery, activeFilter, locations, userPosition, setFilteredLocations, setIsLoading, setError]
  );

  const handleFilterChange = useCallback(
    async (filter: string) => {
      setActiveFilter(filter as LocationType | "ALL");
      setSearchQuery("");
      try {
        setIsLoading(true);
        if (filter === "ALL") {
          setFilteredLocations(locations);
        } else {
          const filtered = locations.filter((loc) => loc.type === filter);
          setFilteredLocations(filtered);
        }
      } finally {
        setIsLoading(false);
      }
    },
    [setActiveFilter, setSearchQuery, locations, setFilteredLocations, setIsLoading]
  );

  // ─── Location Selection ──────────────────────────────────────────

  const handleSelectLocation = useCallback(
    async (location: any) => {
      setSelectedLocation(location);
      setShowLocationPanel(true);
      if (!isMapLocation(location)) return;
      animateToCamera({
        center: [location.longitude, location.latitude],
        zoom: Math.max(camera.zoom, 17),
        pitch: camera.pitch,
        bearing: camera.bearing,
      });
      try {
        const entrances = await mapEntranceService.getEntrances(location.id, location);
        if (entrances.length > 0) {
          const best = await mapEntranceService.selectBestEntrance(
            location.id,
            location,
            { userLocation: userPosition || undefined }
          );
          if (best) setSelectedEntrance(best);
        }
      } catch (err) {
        console.warn(err);
      }
    },
    [setSelectedLocation, setShowLocationPanel, animateToCamera, camera, userPosition, setSelectedEntrance]
  );

  const handleDeselectLocation = useCallback(() => {
    clearSelection();
    setShowLocationPanel(false);
  }, [clearSelection, setShowLocationPanel]);

  // ─── Navigation ──────────────────────────────────────────────────

  const handleStartNavigation = useCallback(async () => {
    if (!selectedLocation || !userPosition) {
      setNavigationError("Missing location or user position");
      return;
    }
    try {
      setIsNavigating(true);
      setNavigationError(null);
      const route = await mapRoutingService.calculateRouteToLocation(
        userPosition,
        selectedLocation
      );
      if (!route) {
        setNavigationError("Unable to calculate route");
        setIsNavigating(false);
        return;
      }
      setCurrentRoute(route);
      if (!isTracking) startTracking();
      setViewMode("navigate");
    } catch (err) {
      setNavigationError(err instanceof Error ? err.message : "Navigation failed");
      setIsNavigating(false);
    }
  }, [selectedLocation, userPosition, setIsNavigating, setNavigationError, setCurrentRoute, isTracking, startTracking, setViewMode]);

  const handleStopNavigation = useCallback(() => {
    setIsNavigating(false);
    setCurrentRoute(null);
    setViewMode("map");
  }, [setIsNavigating, setCurrentRoute, setViewMode]);

  const handleRecenter = useCallback(() => {
    if (!userPosition) {
      setError("User location not available");
      return;
    }
    animateToCamera({
      center: [userPosition.lng, userPosition.lat],
      zoom: 17,
      pitch: 45,
      bearing: -10,
    });
    setIsFollowing(true);
  }, [userPosition, animateToCamera, setIsFollowing, setError]);

  const handleToggleFollowMode = useCallback(() => {
    setIsFollowing(!isFollowing);
  }, [isFollowing, setIsFollowing]);

  // ─── Responsive ──────────────────────────────────────────────────

  useEffect(() => {
    const handleResize = () => {
      setIsCompactMode(window.innerWidth < 768);
    };
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [setIsCompactMode]);

  // ─── Render ──────────────────────────────────────────────────────

  if (isLoading && locations.length === 0) {
    return (
      <div className="flex items-center justify-center h-screen bg-background">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <p className="text-sm text-muted-foreground">Loading campus map...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-background overflow-hidden">
      <GPSPermissionModal
        isOpen={showPermissionModal}
        isLoading={isRequestingPermission}
        onRequestPermission={handleRequestPermission}
        onDismiss={() => {
          setShowPermissionModal(false);
          if (gpsPermissionState !== "granted") setShowPermissionBanner(true);
        }}
      />

      {showPermissionBanner && (
        <GPSPermissionBanner
          permissionState={gpsPermissionState}
          isLoading={isRequestingPermission}
          onRequestPermission={handleRequestPermission}
          onDismiss={() => setShowPermissionBanner(false)}
        />
      )}

      {error && (
        <div className="flex items-center justify-between gap-3 bg-destructive/10 text-destructive px-4 py-3 border-b border-destructive/20 z-20">
          <div className="flex items-center gap-2">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <p className="text-sm font-medium">{error}</p>
          </div>
          <button
            onClick={() => clearError()}
            className="text-xs font-medium hover:opacity-70"
          >
            Dismiss
          </button>
        </div>
      )}

      {viewMode === "map" && (
        <>
          <MapHeader
            searchQuery={searchQuery}
            onSearchChange={handleSearch}
            activeFilter={activeFilter}
            onFilterChange={handleFilterChange}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
            isLoading={isLoading}
          />
          <div className="flex-1 flex overflow-hidden">
            <div className="flex-1 relative">
              <MapCanvas
                locations={filteredLocations.filter(isMapLocation)}
                selectedLocation={selectedLocation}
                onSelectLocation={handleSelectLocation}
                userLocation={userPosition || undefined}
                currentRoute={currentRoute}
              />
              <FloatingControls />
              {filteredLocations.length === 0 && !isLoading && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 pointer-events-none">
                  <MapPin className="w-12 h-12 text-muted-foreground/30" />
                  <p className="text-sm font-medium text-muted-foreground">
                    No locations found
                  </p>
                </div>
              )}
            </div>
            {!isCompactMode && showLocationPanel && selectedLocation && (
              <LocationPanel
                location={selectedLocation}
                onNavigate={handleStartNavigation}
                onClose={handleDeselectLocation}
              />
            )}
          </div>
          {isCompactMode && showLocationPanel && selectedLocation && (
            <div className="fixed inset-x-0 bottom-0 z-30">
              <LocationPanel
                location={selectedLocation}
                onNavigate={handleStartNavigation}
                onClose={handleDeselectLocation}
              />
            </div>
          )}
        </>
      )}

      {viewMode === "navigate" && currentRoute && (
        <NavigationPanel
          route={currentRoute}
          userLocation={userPosition || undefined}
          onStop={handleStopNavigation}
          onExit={() => setViewMode("map")}
        />
      )}
    </div>
  );
}

"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import { Search, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { getCategoriesSorted } from "@/lib/map/config/categories";
import { LocationType } from "@/lib/map/types/location";
import type { MapViewMode } from "@/lib/map/types/map";

interface MapHeaderProps {
  searchQuery: string;
  onSearchChange: (query: string) => void;
  activeFilter: LocationType | "ALL";
  onFilterChange: (filter: LocationType | "ALL") => void;
  viewMode?: MapViewMode;
  onViewModeChange?: (mode: MapViewMode) => void;
  isLoading?: boolean;
}

export function MapHeader({
  searchQuery,
  onSearchChange,
  activeFilter,
  onFilterChange,
  viewMode,
  onViewModeChange,
  isLoading = false,
}: MapHeaderProps) {
  const [localQuery, setLocalQuery] = useState(searchQuery);
  const debounceRef = useRef<NodeJS.Timeout | null>(null);
  const categories = getCategoriesSorted();

  // Sync local state with prop when searchQuery changes externally
  useEffect(() => {
    setLocalQuery(searchQuery);
  }, [searchQuery]);

  const handleSearchChange = useCallback(
    (value: string) => {
      setLocalQuery(value);
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => {
        onSearchChange(value);
      }, 300);
    },
    [onSearchChange]
  );

  const clearSearch = useCallback(() => {
    setLocalQuery("");
    onSearchChange("");
  }, [onSearchChange]);

  return (
    <header className="flex flex-col gap-2 p-3 border-b border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60 z-10">
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            type="search"
            placeholder="Search campus locations..."
            value={localQuery}
            onChange={(e) => handleSearchChange(e.target.value)}
            className="pl-9 pr-8 h-9"
            disabled={isLoading}
          />
          {localQuery && (
            <button
              onClick={clearSearch}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
        {/* Optional view mode toggle if needed */}
        {onViewModeChange && viewMode && (
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              onViewModeChange(viewMode === "map" ? "list" : "map")
            }
            className="hidden md:inline-flex"
          >
            {viewMode === "map" ? "List" : "Map"}
          </Button>
        )}
      </div>

      {/* Category filter pills */}
      <div className="flex gap-1.5 overflow-x-auto pb-1 scrollbar-thin scrollbar-thumb-muted-foreground/20 scrollbar-track-transparent">
        <Button
          variant={activeFilter === "ALL" ? "default" : "outline"}
          size="sm"
          onClick={() => onFilterChange("ALL")}
          className="whitespace-nowrap"
        >
          All
        </Button>
        {categories.map((cat) => (
          <Button
            key={cat.type}
            variant={activeFilter === cat.type ? "default" : "outline"}
            size="sm"
            onClick={() => onFilterChange(cat.type)}
            className="whitespace-nowrap"
          >
            {cat.label}
          </Button>
        ))}
      </div>
    </header>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Loader2, Crosshair } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { GeoJSONLineString } from "@/lib/map/types/geojson";

interface Props {
  routeGeometry: GeoJSONLineString | null;
  userPosition: { lat: number; lng: number } | null;
  nearestVertexIdx: number;
  destination: { lat: number; lng: number } | null;
}

const ROUTE_COLOR_REMAINING = "#FBBC04";
const ROUTE_CASING_COLOR = "#9A6E00";
const ROUTE_WIDTH_REMAINING = 8;
const ROUTE_WIDTH_CASING = 12;
const ROUTE_COLOR_TRAVELED = "#94a3b8";
const ROUTE_WIDTH_TRAVELED = 5;
const MIN_MOVE_METERS = 5;

export default function NavigationMapView({
  routeGeometry,
  userPosition,
  nearestVertexIdx,
  destination,
}: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const userMarkerRef = useRef<any>(null);
  const destMarkerRef = useRef<any>(null);
  const lastCommittedRef = useRef<{ lat: number; lng: number } | null>(null);
  const userInteractedRef = useRef(false);

  const [mapTilerKey, setMapTilerKey] = useState<string | undefined>(undefined);
  const [mapReady, setMapReady] = useState(false);
  const [followPaused, setFollowPaused] = useState(false);

  useEffect(() => {
    import("@/lib/api/campus-map.api")
      .then(({ getMapConfig }) =>
        getMapConfig().then((cfg: any) => setMapTilerKey(cfg.maptilerApiKey || ""))
      )
      .catch(() => setMapTilerKey(""));
  }, []);

  useEffect(() => {
    if (mapRef.current || !containerRef.current || mapTilerKey === undefined) return;
    let cancelled = false;

    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      if (cancelled || !containerRef.current) return;

      const center: [number, number] =
        userPosition
          ? [userPosition.lng, userPosition.lat]
          : destination
          ? [destination.lng, destination.lat]
          : [3.3792, 6.5244];

      const style = mapTilerKey
        ? `https://api.maptiler.com/maps/hybrid/style.json?key=${mapTilerKey}`
        : {
            version: 8 as const,
            sources: {
              osm: {
                type: "raster" as const,
                tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
                tileSize: 256,
                attribution: "© OpenStreetMap contributors",
              },
            },
            layers: [{ id: "osm", type: "raster" as const, source: "osm" }],
          };

      const map = new maplibregl.Map({
        container: containerRef.current!,
        style,
        center,
        zoom: 17,
        pitch: 45,
        bearing: 0,
        antialias: true,
      });

      map.addControl(
        new maplibregl.NavigationControl({ visualizePitch: true }),
        "top-right"
      );

      const pauseFollow = () => {
        if (!userInteractedRef.current) {
          userInteractedRef.current = true;
          setFollowPaused(true);
        }
      };
      map.on("dragstart", pauseFollow);
      map.on("touchstart", pauseFollow);
      map.on("wheel", pauseFollow);

      map.on("load", () => {
        if (cancelled) return;
        map.addSource("route-traveled", {
          type: "geojson",
          data: { type: "Feature", geometry: { type: "LineString", coordinates: [] }, properties: {} },
        });
        map.addSource("route-remaining", {
          type: "geojson",
          data: { type: "Feature", geometry: { type: "LineString", coordinates: [] }, properties: {} },
        });

        map.addLayer({
          id: "route-traveled-line",
          type: "line",
          source: "route-traveled",
          layout: { "line-join": "round", "line-cap": "round" },
          paint: {
            "line-color": ROUTE_COLOR_TRAVELED,
            "line-width": ROUTE_WIDTH_TRAVELED,
            "line-opacity": 0.6,
          },
        });
        map.addLayer({
          id: "route-remaining-casing",
          type: "line",
          source: "route-remaining",
          layout: { "line-join": "round", "line-cap": "round" },
          paint: {
            "line-color": ROUTE_CASING_COLOR,
            "line-width": ROUTE_WIDTH_CASING,
            "line-opacity": 0.9,
          },
        });
        map.addLayer({
          id: "route-remaining-line",
          type: "line",
          source: "route-remaining",
          layout: { "line-join": "round", "line-cap": "round" },
          paint: {
            "line-color": ROUTE_COLOR_REMAINING,
            "line-width": ROUTE_WIDTH_REMAINING,
            "line-opacity": 1,
          },
        });
        setMapReady(true);
      });

      mapRef.current = map;
    })();

    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        userMarkerRef.current = null;
        destMarkerRef.current = null;
      }
    };
  }, [mapTilerKey]);

  // Sync route
  useEffect(() => {
    if (!mapReady || !mapRef.current) return;
    const map = mapRef.current;
    const coords = routeGeometry?.coordinates ?? [];
    const splitAt = Math.max(0, Math.min(nearestVertexIdx, coords.length - 1));
    const traveledSource = map.getSource("route-traveled");
    const remainingSource = map.getSource("route-remaining");
    if (!traveledSource || !remainingSource) return;
    traveledSource.setData({
      type: "Feature",
      geometry: { type: "LineString", coordinates: coords.slice(0, splitAt + 1) },
      properties: {},
    });
    remainingSource.setData({
      type: "Feature",
      geometry: { type: "LineString", coordinates: coords.slice(splitAt) },
      properties: {},
    });
    if (routeGeometry && nearestVertexIdx === 0 && coords.length >= 2) {
      const lngs = coords.map(([lng]) => lng);
      const lats = coords.map(([, lat]) => lat);
      map.fitBounds(
        [
          [Math.min(...lngs), Math.min(...lats)],
          [Math.max(...lngs), Math.max(...lats)],
        ],
        { padding: 80, pitch: 45, duration: 900, maxZoom: 18 }
      );
    }
  }, [routeGeometry, nearestVertexIdx, mapReady]);

  // Destination pin
  useEffect(() => {
    if (!mapReady || !mapRef.current) return;
    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      const map = mapRef.current;
      if (!map) return;
      if (destMarkerRef.current) {
        if (destination) {
          destMarkerRef.current.setLngLat([destination.lng, destination.lat]);
        } else {
          destMarkerRef.current.remove();
          destMarkerRef.current = null;
        }
        return;
      }
      if (!destination) return;
      const el = document.createElement("div");
      el.style.cssText = `
        width: 28px; height: 28px;
        background: #10b981;
        border: 3px solid #fff;
        border-radius: 50% 50% 50% 0;
        transform: rotate(-45deg);
        box-shadow: 0 2px 8px rgba(0,0,0,0.35);
      `;
      destMarkerRef.current = new maplibregl.Marker({ element: el, anchor: "bottom" })
        .setLngLat([destination.lng, destination.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 20, closeButton: false }).setHTML(
            '<span style="font-size:12px;font-family:inherit;font-weight:600">Destination</span>'
          )
        )
        .addTo(map);
    })();
  }, [destination, mapReady]);

  // User position
  useEffect(() => {
    if (!mapReady || !mapRef.current || !userPosition) return;
    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      const map = mapRef.current;
      if (!map) return;
      const prev = lastCommittedRef.current;
      const movedEnough = !prev || haversineM(prev, userPosition) >= MIN_MOVE_METERS;
      if (!movedEnough) return;
      lastCommittedRef.current = userPosition;

      if (userMarkerRef.current) {
        userMarkerRef.current.setLngLat([userPosition.lng, userPosition.lat]);
      } else {
        const el = document.createElement("div");
        el.style.cssText = `
          width: 20px; height: 20px;
          border-radius: 50%;
          background: #3b82f6;
          border: 3px solid #fff;
          box-shadow: 0 0 0 5px rgba(59,130,246,0.25);
        `;
        userMarkerRef.current = new maplibregl.Marker({ element: el, anchor: "center" })
          .setLngLat([userPosition.lng, userPosition.lat])
          .addTo(map);
      }
      if (userInteractedRef.current) return;
      map.easeTo({
        center: [userPosition.lng, userPosition.lat],
        zoom: Math.max(map.getZoom(), 17),
        pitch: 50,
        duration: 800,
      });
    })();
  }, [userPosition, mapReady]);

  function resumeFollow() {
    userInteractedRef.current = false;
    setFollowPaused(false);
    const map = mapRef.current;
    const pos = lastCommittedRef.current;
    if (!map || !pos) return;
    map.easeTo({
      center: [pos.lng, pos.lat],
      zoom: Math.max(map.getZoom(), 17),
      pitch: 50,
      duration: 600,
    });
  }

  return (
    <div className="absolute inset-0">
      <style>{`@import url("https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css");`}</style>
      {mapTilerKey === undefined ? (
        <div className="w-full h-full flex items-center justify-center bg-muted">
          <Loader2 className="w-8 h-8 animate-spin text-primary" />
        </div>
      ) : (
        <div ref={containerRef} className="w-full h-full" />
      )}
      {followPaused && mapReady && (
        <Button
          onClick={resumeFollow}
          variant="default"
          className="absolute bottom-4 right-4 z-20 shadow-lg flex items-center gap-1.5"
        >
          <Crosshair className="w-4 h-4" />
          Re-centre
        </Button>
      )}
    </div>
  );
}

function haversineM(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const R = 6_371_000;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a.lat * Math.PI) / 180) *
      Math.cos((b.lat * Math.PI) / 180) *
      Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

"use client";

import { useEffect, useState } from "react";
import { X, StopCircle, Clock, Footprints } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import NavigationMapView from "./NavigationMapView";
import { mapRoutingService } from "@/lib/map/services";
import { formatDistance, formatDuration } from "@/lib/map/utils/distance";
import type { Route, RouteProgress } from "@/lib/map/types/route";

interface NavigationPanelProps {
  route: Route;
  userLocation?: { lat: number; lng: number };
  onStop: () => void;
  onExit: () => void;
}

export default function NavigationPanel({
  route,
  userLocation,
  onStop,
  onExit,
}: NavigationPanelProps) {
  const [progress, setProgress] = useState<RouteProgress | null>(null);
  const [nearestVertexIdx, setNearestVertexIdx] = useState(0);
  const destination = route.destination;

  // Update progress when user location changes
  useEffect(() => {
    if (!userLocation) return;

    const newProgress = mapRoutingService.calculateRouteProgress(
      route,
      userLocation,
      5 // accuracy in meters
    );
    setProgress(newProgress);

    // Compute nearest vertex index from geometry (simplified fallback)
    const coords = route.geometry.coordinates;
    let minDist = Infinity;
    let idx = 0;
    for (let i = 0; i < coords.length; i++) {
      const [lng, lat] = coords[i];
      const d = Math.hypot(lat - userLocation.lat, lng - userLocation.lng);
      if (d < minDist) {
        minDist = d;
        idx = i;
      }
    }
    setNearestVertexIdx(idx);
  }, [userLocation, route]);

  const remainingDistance = progress?.distanceToEnd ?? route.distance;
  const remainingDuration = progress?.durationToEnd ?? route.duration;

  return (
    <div className="absolute inset-0 z-20 flex flex-col bg-background">
      {/* Full-screen map background */}
      <div className="flex-1 relative">
        <NavigationMapView
          routeGeometry={route.geometry}
          userPosition={userLocation ?? null}
          nearestVertexIdx={nearestVertexIdx}
          destination={destination}
        />

        {/* Overlay controls */}
        <div className="absolute top-4 right-4 flex gap-2">
          <Button
            variant="secondary"
            size="icon"
            onClick={onExit}
            aria-label="Exit navigation"
          >
            <X className="w-5 h-5" />
          </Button>
        </div>

        {/* Bottom sheet */}
        <Card className="absolute bottom-0 left-0 right-0 max-h-[50%] rounded-t-xl shadow-lg border-t border-border overflow-y-auto">
          <CardContent className="p-4 space-y-3">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="font-semibold text-lg">Navigation</h3>
                <p className="text-sm text-muted-foreground">
                  {route.destination.name || "Destination"}
                </p>
              </div>
              <Button variant="destructive" size="sm" onClick={onStop}>
                <StopCircle className="w-4 h-4 mr-2" />
                Stop
              </Button>
            </div>

            {/* Progress stats */}
            <div className="grid grid-cols-2 gap-2">
              <div className="bg-muted rounded-md p-2 flex items-center gap-2">
                <Footprints className="w-4 h-4 text-muted-foreground" />
                <div>
                  <p className="text-xs text-muted-foreground">Distance</p>
                  <p className="font-medium">{formatDistance(remainingDistance)}</p>
                </div>
              </div>
              <div className="bg-muted rounded-md p-2 flex items-center gap-2">
                <Clock className="w-4 h-4 text-muted-foreground" />
                <div>
                  <p className="text-xs text-muted-foreground">Time</p>
                  <p className="font-medium">{formatDuration(remainingDuration)}</p>
                </div>
              </div>
            </div>

            {/* Steps */}
            {route.steps && route.steps.length > 0 ? (
              <div>
                <p className="text-sm font-medium mb-1">Turn-by-turn</p>
                <ol className="space-y-1 text-sm">
                  {route.steps.map((step, idx) => (
                    <li key={idx} className="flex items-start gap-2">
                      <span className="text-muted-foreground min-w-[1.5rem]">
                        {idx + 1}.
                      </span>
                      <span>
                        {step.instruction}
                        <span className="text-xs text-muted-foreground ml-1">
                          ({formatDistance(step.distance)})
                        </span>
                      </span>
                    </li>
                  ))}
                </ol>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">
                Follow the blue route to your destination.
              </p>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef } from "react";
import { Loader2 } from "lucide-react";

interface MapLocation {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  type: string;
  description?: string | null;
  imageUrl?: string | null;
}

interface Props {
  locations: MapLocation[];
  onSelectLocation?: (location: MapLocation) => void;
  selectedId?: string;
  userLocation?: { lat: number; lng: number } | null;
  routeGeoJson?: any | null;
}

const TYPE_COLORS: Record<string, string> = {
  LIBRARY: "#0ea5e9",
  BUILDING: "#6366f1",
  HOSTEL: "#10b981",
  CAFETERIA: "#f59e0b",
  CLINIC: "#f43f5e",
  SPORTS: "#f97316",
  GATE: "#64748b",
  PARKING: "#3b82f6",
  OFFICE: "#a855f7",
  LAB: "#14b8a6",
  LECTURE_HALL: "#818cf8",
  OTHER: "#94a3b8",
  UNKNOWN: "#94a3b8",
};
function colorFor(type: string) {
  return TYPE_COLORS[type] ?? TYPE_COLORS.UNKNOWN;
}

function pinSvg(color: string) {
  return `
    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 32 32">
      <circle cx="16" cy="16" r="13" fill="${color}" stroke="white" stroke-width="3"/>
    </svg>`.trim();
}

function svgToDataUrl(svg: string) {
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}

export default function StudentMapViewer({
  locations,
  onSelectLocation,
  selectedId,
  userLocation,
  routeGeoJson,
}: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const markersRef = useRef<Map<string, any>>(new Map());
  const userMarkerRef = useRef<any>(null);
  const [mapTilerKey, setMapTilerKey] = React.useState<string | undefined>(undefined);
  const [mapReady, setMapReady] = React.useState(false);

  React.useEffect(() => {
    import("@/lib/api/campus-map.api")
      .then(({ getMapConfig }) =>
        getMapConfig().then((cfg: any) => setMapTilerKey(cfg.maptilerApiKey || ""))
      )
      .catch(() => setMapTilerKey(""));
  }, []);

  useEffect(() => {
    if (mapRef.current || !containerRef.current || mapTilerKey === undefined) return;
    let cancelled = false;

    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      if (cancelled || !containerRef.current) return;

      const center: [number, number] =
        locations.length > 0
          ? [
              locations.reduce((s, l) => s + l.longitude, 0) / locations.length,
              locations.reduce((s, l) => s + l.latitude, 0) / locations.length,
            ]
          : [4.5399, 7.3775];

      const style = mapTilerKey
        ? `https://api.maptiler.com/maps/hybrid/style.json?key=${mapTilerKey}`
        : {
            version: 8 as const,
            sources: {
              osm: {
                type: "raster" as const,
                tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
                tileSize: 256,
                attribution: "© OpenStreetMap contributors",
              },
            },
            layers: [{ id: "osm", type: "raster" as const, source: "osm" }],
          };

      const map = new maplibregl.Map({
        container: containerRef.current!,
        style,
        center,
        zoom: locations.length > 0 ? 16 : 14,
        pitch: 45,
        bearing: -10,
        antialias: true,
      });

      map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");

      map.on("load", () => {
        if (cancelled) return;
        setMapReady(true);

        // --- FIXED 3D BUILDINGS SECTION ---
        if (mapTilerKey) {
          try {
            // Determine which source provides building data
            const sourceCandidates = ["maptiler_planet", "openmaptiles", "composite"];
            let sourceId: string | null = null;
            for (const id of sourceCandidates) {
              if (map.getSource(id)) {
                sourceId = id;
                break;
              }
            }

            if (sourceId) {
              const firstSymbolId = map.getStyle().layers?.find(
                (l: any) => l.type === "symbol"
              )?.id;

              map.addLayer(
                {
                  id: "3d-buildings",
                  source: sourceId,
                  "source-layer": "building",
                  type: "fill-extrusion",
                  minzoom: 14,
                  paint: {
                    "fill-extrusion-color": [
                      "interpolate",
                      ["linear"],
                      ["zoom"],
                      14,
                      "#d1d5db",
                      16,
                      "#9ca3af",
                    ],
                    "fill-extrusion-height": [
                      "interpolate",
                      ["linear"],
                      ["zoom"],
                      14,
                      0,
                      14.5,
                      ["coalesce", ["get", "render_height"], ["get", "height"], 6],
                    ],
                    "fill-extrusion-base": [
                      "interpolate",
                      ["linear"],
                      ["zoom"],
                      14,
                      0,
                      14.5,
                      ["coalesce", ["get", "render_min_height"], ["get", "min_height"], 0],
                    ],
                    "fill-extrusion-opacity": 0.7,
                  },
                },
                firstSymbolId
              );
            }
          } catch {
            // Ignore – 3D buildings are non‑critical
          }
        }
        // --- END OF FIXED SECTION ---
      });

      mapRef.current = map;
    })();

    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        userMarkerRef.current = null;
        markersRef.current.clear();
      }
    };
  }, [mapTilerKey]);

  // Sync markers
  useEffect(() => {
    if (!mapReady || !mapRef.current) return;
    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      const map = mapRef.current;
      if (!map) return;

      const markers = markersRef.current;
      const seen = new Set<string>();

      locations.forEach((loc) => {
        seen.add(loc.id);
        const isSelected = selectedId === loc.id;
        const size = isSelected ? 36 : 28;
        const color = colorFor(loc.type);

        if (markers.has(loc.id)) {
          markers.get(loc.id).setLngLat([loc.longitude, loc.latitude]);
          const el = markers.get(loc.id).getElement();
          el.style.width = `${size}px`;
          el.style.height = `${size}px`;
          el.style.zIndex = isSelected ? "2" : "1";
          return;
        }

        const el = document.createElement("div");
        el.style.width = `${size}px`;
        el.style.height = `${size}px`;
        el.style.cursor = "pointer";
        el.style.backgroundImage = `url("${svgToDataUrl(pinSvg(color))}")`;
        el.style.backgroundSize = "contain";
        el.style.backgroundRepeat = "no-repeat";
        el.style.transition = "width .15s, height .15s";
        el.style.zIndex = isSelected ? "2" : "1";
        el.style.filter = isSelected
          ? "drop-shadow(0 0 6px rgba(0,0,0,.5))"
          : "drop-shadow(0 2px 3px rgba(0,0,0,.35))";

        const popup = new maplibregl.Popup({ offset: 25, closeButton: false }).setHTML(
          `<div style="font-family:inherit;padding:4px 2px">
            <strong style="font-size:13px">${loc.name}</strong>
            ${loc.type ? `<br/><small style="color:#6b7280">${loc.type.replace(/_/g, " ")}</small>` : ""}
            ${loc.description ? `<br/><span style="font-size:11px;color:#374151">${loc.description}</span>` : ""}
          </div>`
        );

        const marker = new maplibregl.Marker({ element: el, anchor: "bottom" })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(popup)
          .addTo(map);

        el.addEventListener("click", (e) => {
          e.stopPropagation();
          if (onSelectLocation) onSelectLocation(loc);
        });

        markers.set(loc.id, marker);
      });

      markers.forEach((marker, id) => {
        if (!seen.has(id)) {
          marker.remove();
          markers.delete(id);
        }
      });
    })();
  }, [locations, selectedId, onSelectLocation, mapReady]);

  // Pan to selected
  useEffect(() => {
    if (!mapReady || !mapRef.current || !selectedId) return;
    const loc = locations.find((l) => l.id === selectedId);
    if (!loc) return;
    mapRef.current.easeTo({
      center: [loc.longitude, loc.latitude],
      zoom: Math.max(mapRef.current.getZoom(), 17),
      pitch: 50,
      duration: 600,
    });
  }, [selectedId, locations, mapReady]);

  // Route
  useEffect(() => {
    if (!mapReady || !mapRef.current) return;
    const map = mapRef.current;
    if (map.getLayer("route-line")) map.removeLayer("route-line");
    if (map.getLayer("route-casing")) map.removeLayer("route-casing");
    if (map.getSource("route")) map.removeSource("route");
    if (!routeGeoJson) return;
    try {
      map.addSource("route", { type: "geojson", data: routeGeoJson });
      map.addLayer({
        id: "route-casing",
        type: "line",
        source: "route",
        layout: { "line-join": "round", "line-cap": "round" },
        paint: { "line-color": "#ffffff", "line-width": 9, "line-opacity": 0.8 },
      });
      map.addLayer({
        id: "route-line",
        type: "line",
        source: "route",
        layout: { "line-join": "round", "line-cap": "round" },
        paint: {
          "line-color": "#6366f1",
          "line-width": 5,
          "line-opacity": 0.95,
          "line-dasharray": [2, 1.5],
        },
      });
      // fit bounds
      const coords: [number, number][] = [];
      function collect(geom: any) {
        if (!geom) return;
        if (geom.type === "LineString") coords.push(...geom.coordinates);
        if (geom.type === "FeatureCollection")
          geom.features?.forEach((f: any) => collect(f.geometry));
        if (geom.type === "Feature") collect(geom.geometry);
      }
      collect(routeGeoJson);
      if (coords.length >= 2) {
        const lngs = coords.map(([lng]) => lng);
        const lats = coords.map(([, lat]) => lat);
        map.fitBounds(
          [
            [Math.min(...lngs), Math.min(...lats)],
            [Math.max(...lngs), Math.max(...lats)],
          ],
          { padding: 60, pitch: 50, duration: 800 }
        );
      }
    } catch (e) {
      console.warn("Failed to render route", e);
    }
  }, [routeGeoJson, mapReady]);

  // User location
  useEffect(() => {
    if (!mapReady || !mapRef.current) return;
    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      const map = mapRef.current;
      if (!map) return;
      if (userMarkerRef.current) {
        userMarkerRef.current.remove();
        userMarkerRef.current = null;
      }
      if (!userLocation) return;
      const el = document.createElement("div");
      el.style.width = "18px";
      el.style.height = "18px";
      el.style.borderRadius = "50%";
      el.style.background = "#6366f1";
      el.style.border = "3px solid #fff";
      el.style.boxShadow = "0 0 0 4px rgba(99,102,241,0.3)";
      userMarkerRef.current = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([userLocation.lng, userLocation.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 14, closeButton: false }).setHTML(
            '<span style="font-size:12px;font-family:inherit">Your location</span>'
          )
        )
        .addTo(map);
    })();
  }, [userLocation, mapReady]);

  return (
    <div className="relative w-full h-full">
      <style>{`@import url("https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css");`}</style>
      {mapTilerKey === undefined ? (
        <div className="w-full h-full flex items-center justify-center bg-muted">
          <Loader2 className="w-6 h-6 animate-spin text-primary" />
        </div>
      ) : (
        <div ref={containerRef} className="w-full h-full" />
      )}
      {mapReady && mapTilerKey && (
        <div className="absolute bottom-10 right-3 z-10 bg-card/90 backdrop-blur-sm rounded-xl px-3 py-1.5 text-xs text-muted-foreground shadow pointer-events-none">
          🏢 3D buildings on
        </div>
      )}
    </div>
  );
}

