      const deserialized = JSON.parse(serialized);

      expect(deserialized).toBe(value);
    });
  });

  // ============================================================
  // Initial Value Tests
  // ============================================================

  describe('Initial Value Handling', () => {
    it('should use initialValue if key is not in localStorage', () => {
      const key = 'nonexistent_key';
