/**
 * useGPSTracking — Hook for GPS location tracking with permissions
 * 
 * Features:
 * - Request geolocation permission
 * - Start/stop continuous GPS tracking
 * - Detect permission state (unknown, granted, denied)
 * - Handle permission changes (e.g. user grants in browser settings)
 * - Battery-efficient (disable high accuracy when not needed)
 * - Error handling and recovery
 */

import { useEffect, useCallback, useRef, useState } from 'react';

export type PermissionState = 'unknown' | 'prompt' | 'granted' | 'denied';

export interface GPSPosition {
  lat: number;
  lng: number;
  accuracy?: number;
  timestamp?: number;
}

export interface UseGPSTrackingReturn {
  position: GPSPosition | null;
  isTracking: boolean;
  permissionState: PermissionState;
  error: string | null;
  requestPermission: () => Promise<void>;
  startTracking: () => void;
  stopTracking: () => void;
}

/**
 * Hook for GPS tracking
 * 
 * @param enableHighAccuracy - Use high accuracy mode (better but drains battery)
 * @param timeout - Timeout for position requests (ms)
 * @param maximumAge - Cache position for this duration (ms)
 */
export function useGPSTracking(
  enableHighAccuracy = false,
  timeout = 10000,
  maximumAge = 0,
): UseGPSTrackingReturn {
  const [position, setPosition] = useState<GPSPosition | null>(null);
  const [isTracking, setIsTracking] = useState(false);
  const [permissionState, setPermissionState] = useState<PermissionState>('unknown');
  const [error, setError] = useState<string | null>(null);

  const watchIdRef = useRef<number | null>(null);
  const permissionListenerRef = useRef<PermissionStatus | null>(null);

  const normalizePermissionState = (state: globalThis.PermissionState): PermissionState =>
    state === 'prompt' ? 'prompt' : state;

  /**
   * Check initial permission state and setup listener
   */
  useEffect(() => {
    if (!navigator.geolocation) {
      setPermissionState('denied');
      setError('Geolocation not available');
      return;
    }

    // Try to use Permissions API (not available in all browsers)
    if (navigator.permissions) {
      navigator.permissions
        .query({ name: 'geolocation' })
        .then((result) => {
          setPermissionState(normalizePermissionState(result.state));
          permissionListenerRef.current = result;

          // Listen for permission changes (e.g. user grants in settings)
          result.addEventListener('change', () => {
            setPermissionState(normalizePermissionState(result.state));
            setError(null);
          });
        })
        .catch(() => {
          // Permissions API not available — permission state is unknown
          setPermissionState('unknown');
        });
    } else {
      // Permissions API not available
      setPermissionState('unknown');
    }

    return () => {
      if (permissionListenerRef.current) {
        permissionListenerRef.current.removeEventListener('change', () => {});
      }
    };
  }, []);

  /**
   * Request geolocation permission from user
   */
  const requestPermission = useCallback(async () => {
    if (!navigator.geolocation) {
      setPermissionState('denied');
      setError('Geolocation not available');
      return;
    }

    return new Promise<void>((resolve) => {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setPosition({
            lat: pos.coords.latitude,
            lng: pos.coords.longitude,
            accuracy: pos.coords.accuracy,
            timestamp: pos.timestamp,
          });
          setPermissionState('granted');
          setError(null);
          resolve();
        },
        (err) => {
          if (err.code === err.PERMISSION_DENIED) {
            setPermissionState('denied');
            setError('Location permission denied');
          } else if (err.code === err.POSITION_UNAVAILABLE) {
            setError('Position unavailable');
          } else if (err.code === err.TIMEOUT) {
            setError('Position request timeout');
          } else {
            setError('Unknown geolocation error');
          }
          resolve();
        },
        {
          enableHighAccuracy,
          timeout,
          maximumAge,
        },
      );
    });
  }, [enableHighAccuracy, timeout, maximumAge]);

  /**
   * Start GPS tracking — continuously update position
   */
  const startTracking = useCallback(() => {
    if (!navigator.geolocation) {
      setError('Geolocation not available');
      return;
    }

    if (watchIdRef.current !== null) {
      return; // Already tracking
    }

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        setPosition({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          accuracy: pos.coords.accuracy,
          timestamp: pos.timestamp,
        });
        setError(null);
        setIsTracking(true);
      },
      (err) => {
        console.error('GPS tracking error:', err);
        if (err.code === err.PERMISSION_DENIED) {
          setPermissionState('denied');
          setError('Location permission denied');
        } else if (err.code === err.POSITION_UNAVAILABLE) {
          setError('Position unavailable');
        } else if (err.code === err.TIMEOUT) {
          // Timeout is not critical — keep trying
          console.warn('Position request timeout');
        } else {
          setError('GPS error: ' + err.message);
        }
      },
      {
        enableHighAccuracy: true, // Use high accuracy for navigation
        timeout,
        maximumAge: 0, // Always get fresh position
      },
    );

    watchIdRef.current = watchId;
    setIsTracking(true);
  }, [timeout]);

  /**
   * Stop GPS tracking
   */
  const stopTracking = useCallback(() => {
    if (watchIdRef.current !== null && navigator.geolocation) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setIsTracking(false);
  }, []);

  /**
   * Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      stopTracking();
      if (permissionListenerRef.current) {
        permissionListenerRef.current.removeEventListener('change', () => {});
      }
    };
  }, [stopTracking]);

  return {
    position,
    isTracking,
    permissionState,
    error,
    requestPermission,
    startTracking,
    stopTracking,
  };
}

/**
 * Entrance normalization — converts API responses into normalized Entrance objects
 * 
 * Entrances are typically GeoJSON Point features from:
 * - GET /campus-map/features/{id}/entrances (FeatureCollection)
 * - Admin: GET /super-admin/map/schools/{schoolId}/entrances
 */

import { Entrance, EntranceKind } from '../types/entrance';
import { GeoJSONFeature } from '../types/geojson';

export interface RawEntranceData extends Record<string, unknown> {
  id?: string;
  _id?: string;
  name?: string;
  kind?: string;
  tag?: string;
  type?: string;
  isAccessible?: boolean;
  accessible?: boolean;
  latitude?: number;
  lat?: number;
  longitude?: number;
  lng?: number;
  description?: string;
  metadata?: Record<string, unknown>;
  geometry?: unknown;
  properties?: Record<string, unknown>;
  accessibility?: Record<string, unknown>;
  openingHours?: string;
  contactInfo?: string;
  notes?: string;
}

/**
 * Normalize a raw entrance object or GeoJSON Feature into a standardized Entrance
 * 
 * Entrances must always have coordinates (they represent points of entry)
 * If coordinates are missing, returns null
 */
export function normalizeEntrance(raw: RawEntranceData | GeoJSONFeature): Entrance | null {
  if (!raw) return null;

  // Extract ID (optional but helpful)
  const id = extractId(raw) || generateId();

  // Extract name
  const name = extractName(raw);
  if (!name) return null;

  // Extract coordinates (required for entrance)
  const coords = extractEntranceCoordinates(raw);
  if (!coords) return null;

  const [lng, lat] = coords;

  // Extract entrance kind/type
  const kind = extractEntranceKind(raw);

  // Extract accessibility info
  const isAccessible = extractIsAccessible(raw);
  const accessibility = extractAccessibility(raw);

  // Extract optional fields
  const description = extractDescription(raw);
  const metadata = extractMetadata(raw);

  return {
    id,
    name,
    kind,
    isAccessible,
    accessibility,
    latitude: lat,
    longitude: lng,
    description: description || undefined,
    metadata,
  };
}

/**
 * Normalize an array of raw entrances
 */
export function normalizeEntrances(raws: (RawEntranceData | GeoJSONFeature)[]): Entrance[] {
  return raws
    .map(raw => normalizeEntrance(raw))
    .filter((entrance): entrance is Entrance => entrance !== null);
}

/**
 * Create fallback entrances from location tags when backend doesn't provide explicit entrance data
 * 
 * Example: if a building has tags ["MAIN", "ACCESSIBLE"], create entrance objects from those
 * This is a temporary workaround; proper entrance data should come from backend
 */
export function createFallbackEntrances(locationName: string, locationId: string, tags?: string[]): Entrance[] {
  if (!tags || tags.length === 0) {
    // If no tags, create a single generic entrance
    return [
      {
        id: `${locationId}-entrance-main`,
        name: `${locationName} Entrance`,
        kind: 'MAIN',
        latitude: 0, // Placeholder — should not be used for navigation
        longitude: 0,
      },
    ];
  }

  return tags
    .filter(tag => typeof tag === 'string' && tag.trim())
    .map((tag, index) => {
      const entrance: Entrance = {
        id: `${locationId}-entrance-${index}`,
        name: `${tag.replace(/_/g, ' ')} Entrance`,
        kind: normalizeEntranceKindFromTag(tag) || 'OTHER',
        isAccessible: /accessible|wheelchair|disabled/i.test(tag),
        latitude: 0, // Placeholder
        longitude: 0,
      };
      return entrance;
    });
}

// ─── Extraction helpers ────────────────────────────────────────────────────────

function extractId(raw: any): string | null {
  const id = raw.id || raw._id || raw.properties?.id;
  return typeof id === 'string' && id.trim() ? id : null;
}

function generateId(): string {
  return `entrance-${crypto.randomUUID()}`;
}

function extractName(raw: any): string | null {
  const name = raw.name || raw.properties?.name;
  if (typeof name === 'string' && name.trim()) return name.trim();

  // Fallback to properties.kind or tag
  const kind = raw.kind || raw.tag || raw.properties?.kind || raw.properties?.tag;
  if (typeof kind === 'string' && kind.trim()) {
    return `${kind.replace(/_/g, ' ')} Entrance`;
  }

  return null;
}

function extractEntranceCoordinates(raw: any): [number, number] | null {
  // GeoJSON Point geometry
  if (raw.geometry?.type === 'Point' && Array.isArray(raw.geometry.coordinates)) {
    const [lng, lat] = raw.geometry.coordinates;
    if (typeof lng === 'number' && typeof lat === 'number') {
      return [lng, lat];
    }
  }

  // Top-level coordinates
  const lat = typeof raw.latitude === 'number' ? raw.latitude : typeof raw.lat === 'number' ? raw.lat : null;
  const lng = typeof raw.longitude === 'number' ? raw.longitude : typeof raw.lng === 'number' ? raw.lng : null;

  if (typeof lat === 'number' && typeof lng === 'number') {
    return [lng, lat];
  }

  // Properties coordinates
  const propLat = typeof raw.properties?.latitude === 'number' ? raw.properties.latitude : null;
  const propLng = typeof raw.properties?.longitude === 'number' ? raw.properties.longitude : null;

  if (typeof propLat === 'number' && typeof propLng === 'number') {
    return [propLng, propLat];
  }

  return null;
}

function extractEntranceKind(raw: any): EntranceKind | undefined {
  const kind = raw.kind || raw.tag || raw.type || raw.properties?.kind || raw.properties?.tag;
  return normalizeEntranceKindFromTag(kind);
}

function normalizeEntranceKindFromTag(tag: unknown): EntranceKind | undefined {
  if (typeof tag !== 'string') return undefined;

  const normalized = tag.toUpperCase();
  const validKinds: EntranceKind[] = ['MAIN', 'SIDE', 'SERVICE', 'ACCESSIBLE', 'EMERGENCY', 'OTHER'];

  if (validKinds.includes(normalized as EntranceKind)) {
    return normalized as EntranceKind;
  }

  // Heuristic: if it contains certain keywords, map to appropriate kind
  if (/main|primary/i.test(tag)) return 'MAIN';
  if (/side|secondary/i.test(tag)) return 'SIDE';
  if (/service|delivery|loading/i.test(tag)) return 'SERVICE';
  if (/accessible|wheelchair|disabled/i.test(tag)) return 'ACCESSIBLE';
  if (/emergency|evacuation/i.test(tag)) return 'EMERGENCY';

  return undefined;
}

function extractIsAccessible(raw: any): boolean | undefined {
  const accessible = raw.isAccessible ?? raw.accessible ?? raw.properties?.isAccessible;

  if (typeof accessible === 'boolean') return accessible;

  // Check accessibility object
  const a11y = raw.accessibility || raw.properties?.accessibility;
  if (typeof a11y === 'object' && a11y !== null) {
    return Boolean(a11y.wheelchair || a11y.visual || a11y.hearing || a11y.mobility);
  }

  return undefined;
}

function extractAccessibility(raw: any): Entrance['accessibility'] | undefined {
  const a11y = raw.accessibility || raw.properties?.accessibility;

  if (typeof a11y === 'object' && a11y !== null) {
    return {
      wheelchair: Boolean(a11y.wheelchair),
      visual: Boolean(a11y.visual),
      hearing: Boolean(a11y.hearing),
      mobility: Boolean(a11y.mobility),
    };
  }

  return undefined;
}

function extractDescription(raw: any): string | null {
  const desc = raw.description || raw.properties?.description;
  return typeof desc === 'string' ? desc.trim() || null : null;
}

function extractMetadata(raw: any): Entrance['metadata'] | undefined {
  const metadata: Entrance['metadata'] = {};

  const openingHours = raw.openingHours || raw.properties?.openingHours;
  if (typeof openingHours === 'string') metadata.openingHours = openingHours;

  const contactInfo = raw.contactInfo || raw.properties?.contactInfo;
  if (typeof contactInfo === 'string') metadata.contactInfo = contactInfo;

  const notes = raw.notes || raw.properties?.notes;
  if (typeof notes === 'string') metadata.notes = notes;

  // Merge existing metadata object
  const existing = raw.metadata || raw.properties?.metadata;
  if (typeof existing === 'object' && existing !== null) {
    Object.assign(metadata, existing);
  }

  return Object.keys(metadata).length > 0 ? metadata : undefined;
}

/**
 * Location normalization — converts API responses into normalized Location objects
 * 
 * Handles multiple response shapes:
 * 1. GeoJSON Feature (from /campus-map/features/{id})
 * 2. Flat object (from /campus-map/search results)
 * 3. Nested properties (from /campus-map/nearest)
 */

import { Location, LocationType, isValidLocationType } from '../types/location';
import { GeoJSONFeature, extractCoordinates, calculateCentroid } from '../types/geojson';

export interface RawLocationData extends Record<string, unknown> {
  id?: string;
  _id?: string;
  name?: string;
  type?: string;
  category?: string;
  description?: string;
  latitude?: number;
  lat?: number;
  longitude?: number;
  lng?: number;
  images?: string[];
  imageUrl?: string;
  tags?: string[];
  distanceMeters?: number;
  geometry?: unknown;
  properties?: Record<string, unknown>;
  centroid?: unknown;
  floor?: string;
  capacity?: number;
  isOpen?: boolean;
  metadata?: Record<string, unknown>;
}

/**
 * Normalize a raw location object or GeoJSON Feature into a standardized Location
 * 
 * Priority order for coordinate extraction:
 * 1. GeoJSON geometry (Point)
 * 2. GeoJSON geometry centroid (for Polygon/MultiPolygon)
 * 3. Top-level latitude/longitude or lat/lng
 * 4. properties.latitude/longitude
 * 5. Return null if no coordinates available
 * 
 * Priority order for location type:
 * 1. category (most common in API)
 * 2. type
 * 3. properties.category
 * 4. properties.type
 * 5. Defaults to "OTHER"
 */
export function normalizeLocation(raw: RawLocationData | GeoJSONFeature): Location | null {
  if (!raw) return null;

  // Extract ID
  const id = extractId(raw);
  if (!id) return null;

  // Extract name
  const name = extractName(raw);
  if (!name) return null;

  // Extract location type
  const type = extractLocationType(raw);

  // Extract coordinates
  const coords = extractLocationCoordinates(raw);
  if (!coords) return null;

  const [lng, lat] = coords;

  // Extract optional fields
  const description = extractDescription(raw);
  const images = extractImages(raw);
  const tags = extractTags(raw);
  const distanceM = extractDistance(raw);
  const floor = extractFloor(raw);
  const capacity = extractCapacity(raw);
  const isOpen = extractIsOpen(raw);
  const metadata = extractMetadata(raw);

  // Extract geometry for map rendering
  const geometry = extractGeometry(raw);

  return {
    id,
    name,
    type,
    description: description || null,
    tags,
    latitude: lat,
    longitude: lng,
    geometry,
    images,
    imageUrl: images?.[0] || null,
    distanceM: distanceM || null,
    floor: floor || null,
    capacity,
    isOpen,
    metadata,
  };
}

/**
 * Normalize an array of raw locations
 */
export function normalizeLocations(raws: RawLocationData[] | GeoJSONFeature[]): Location[] {
  return raws
    .map(raw => normalizeLocation(raw))
    .filter((loc): loc is Location => loc !== null);
}

// ─── Extraction helpers ────────────────────────────────────────────────────────

function extractId(raw: any): string | null {
  const id = raw.id || raw._id || raw.properties?.id;
  return typeof id === 'string' && id.trim() ? id : null;
}

function extractName(raw: any): string | null {
  const name = raw.name || raw.properties?.name;
  return typeof name === 'string' && name.trim() ? name.trim() : null;
}

function extractLocationType(raw: any): LocationType {
  const candidates = [
    raw.category,
    raw.type,
    raw.properties?.category,
    raw.properties?.type,
  ];

  for (const candidate of candidates) {
    if (isValidLocationType(candidate)) return candidate;
  }

  return 'OTHER';
}

function extractLocationCoordinates(raw: any): [number, number] | null {
  // GeoJSON Feature with geometry
  if (raw.geometry) {
    // Point geometry
    if (raw.geometry.type === 'Point' && Array.isArray(raw.geometry.coordinates)) {
      const [lng, lat] = raw.geometry.coordinates;
      if (typeof lng === 'number' && typeof lat === 'number') {
        return [lng, lat];
      }
    }

    // Non-Point geometry: use centroid
    if (raw.geometry.type !== 'Point' && raw.geometry.coordinates) {
      const centroidCoords = raw.properties?.centroid?.coordinates || raw.centroid?.coordinates;
      if (Array.isArray(centroidCoords)) {
        const [lng, lat] = centroidCoords;
        if (typeof lng === 'number' && typeof lat === 'number') {
          return [lng, lat];
        }
      }

      // Fallback: calculate centroid
      const calculated = calculateCentroid(raw.geometry);
      if (calculated) return calculated;
    }
  }

  // Top-level coordinates
  const lat = typeof raw.latitude === 'number' ? raw.latitude : typeof raw.lat === 'number' ? raw.lat : null;
  const lng = typeof raw.longitude === 'number' ? raw.longitude : typeof raw.lng === 'number' ? raw.lng : null;

  if (typeof lat === 'number' && typeof lng === 'number') {
    return [lng, lat];
  }

  // Properties coordinates
  const propLat = typeof raw.properties?.latitude === 'number' ? raw.properties.latitude : null;
  const propLng = typeof raw.properties?.longitude === 'number' ? raw.properties.longitude : null;

  if (typeof propLat === 'number' && typeof propLng === 'number') {
    return [propLng, propLat];
  }

  return null;
}

function extractDescription(raw: any): string | null {
  const desc = raw.description || raw.properties?.description;
  return typeof desc === 'string' ? desc.trim() || null : null;
}

function extractImages(raw: any): string[] | undefined {
  const images = raw.images || raw.properties?.images;
  if (Array.isArray(images)) {
    return images.filter((img): img is string => typeof img === 'string');
  }
  return undefined;
}

function extractTags(raw: any): string[] | undefined {
  const tags = raw.tags || raw.properties?.tags;
  if (Array.isArray(tags)) {
    return tags.filter((tag): tag is string => typeof tag === 'string');
  }
  return undefined;
}

function extractDistance(raw: any): number | null {
  const dist = raw.distanceMeters || raw.distance;
  return typeof dist === 'number' ? dist : null;
}

function extractFloor(raw: any): string | null {
  const floor = raw.floor || raw.properties?.floor;
  return typeof floor === 'string' ? floor.trim() || null : null;
}

function extractCapacity(raw: any): number | undefined {
  const capacity = raw.capacity || raw.properties?.capacity;
  return typeof capacity === 'number' ? capacity : undefined;
}

function extractIsOpen(raw: any): boolean | undefined {
  const isOpen = raw.isOpen || raw.properties?.isOpen;
  return typeof isOpen === 'boolean' ? isOpen : undefined;
}

function extractMetadata(raw: any): Record<string, unknown> | undefined {
  const metadata = raw.metadata || raw.properties?.metadata;
  return typeof metadata === 'object' && metadata !== null ? metadata : undefined;
}

function extractGeometry(raw: any): Location['geometry'] | undefined {
  if (!raw.geometry || typeof raw.geometry !== 'object') return undefined;

  const { type, coordinates } = raw.geometry;
  if (!type || !coordinates) return undefined;

  // Only preserve geometries we can render
  if (['Point', 'Polygon', 'MultiPolygon', 'LineString'].includes(type)) {
    return { type, coordinates };
  }

  return undefined;
}

/**
 * Route normalization — converts API responses into normalized Route objects
 * 
 * Backend returns routing data from POST /campus-map/route
 */

import { Route, RoutingMode, RouteStep } from '../types/route';
import { GeoJSONLineString } from '../types/geojson';

export interface RawRouteData extends Record<string, unknown> {
  id?: string;
  geometry?: unknown;
  distance?: number;
  duration?: number;
  steps?: unknown[];
  waypoints?: unknown[];
  mode?: string;
  summary?: string;
  alternatives?: unknown[];
  origin?: unknown;
  destination?: unknown;
  routes?: unknown[];
  code?: string;
}

/**
 * Normalize a raw route response from the backend
 */
export function normalizeRoute(
  raw: RawRouteData,
  origin?: { lat: number; lng: number; name?: string },
  destination?: { lat: number; lng: number; name?: string },
): Route | null {
  if (!raw) return null;

  // Handle wrapped format: { routes: [...] }
  let routeData = raw;
  if (Array.isArray(raw.routes) && raw.routes.length > 0) {
    routeData = raw.routes[0] as RawRouteData;
  }

  // Extract geometry
  const geometry = extractGeometry(routeData);
  if (!geometry) return null;

  // Extract endpoints
  const extractedOrigin = extractEndpoint(routeData.origin) || origin;
  const extractedDestination = extractEndpoint(routeData.destination) || destination;

  if (!extractedOrigin || !extractedDestination) return null;

  // Extract metrics
  const distance = extractDistance(routeData);
  const duration = extractDuration(routeData);
  const mode = extractMode(routeData);
  const steps = extractSteps(routeData);
  const waypoints = extractWaypoints(routeData);
  const summary = extractSummary(routeData);

  return {
    id: routeData.id || generateRouteId(),
    createdAt: new Date(),
    origin: extractedOrigin,
    destination: extractedDestination,
    geometry,
    distance: distance || 0,
    duration: duration || 0,
    steps,
    waypoints,
    mode,
    summary: summary || undefined,
  };
}

/**
 * Normalize multiple routes (alternatives)
 */
export function normalizeRoutes(
  raws: RawRouteData[],
  origin?: { lat: number; lng: number; name?: string },
  destination?: { lat: number; lng: number; name?: string },
): Route[] {
  return raws
    .map(raw => normalizeRoute(raw, origin, destination))
    .filter((route): route is Route => route !== null);
}

// ─── Extraction helpers ────────────────────────────────────────────────────────

function generateRouteId(): string {
  return `route-${crypto.randomUUID()}`;
}

function extractGeometry(raw: any): GeoJSONLineString | null {
  const geom = raw.geometry;

  // GeoJSON format
  if (geom && typeof geom === 'object') {
    if (geom.type === 'LineString' && Array.isArray(geom.coordinates)) {
      return geom as GeoJSONLineString;
    }

    // Flat coordinates array
    if (Array.isArray(geom)) {
      return {
        type: 'LineString',
        coordinates: geom,
      };
    }
  }

  // Try polyline string
  if (typeof raw.polyline === 'string') {
    const decoded = decodePolyline(raw.polyline);
    if (decoded && decoded.length > 0) {
      return {
        type: 'LineString',
        coordinates: decoded,
      };
    }
  }

  return null;
}

function extractEndpoint(endpoint: unknown): { lat: number; lng: number; name?: string } | null {
  if (!endpoint || typeof endpoint !== 'object') return null;

  const e = endpoint as Record<string, unknown>;
  const lat = typeof e.lat === 'number' ? e.lat : typeof e.latitude === 'number' ? e.latitude : null;
  const lng = typeof e.lng === 'number' ? e.lng : typeof e.longitude === 'number' ? e.longitude : null;
  const name = typeof e.name === 'string' ? e.name : undefined;

  if (typeof lat === 'number' && typeof lng === 'number') {
    return { lat, lng, name };
  }

  return null;
}

function extractDistance(raw: any): number | null {
  const distance = raw.distance || raw.distances?.[0];
  return typeof distance === 'number' && distance > 0 ? distance : null;
}

function extractDuration(raw: any): number | null {
  const duration = raw.duration || raw.durations?.[0];
  return typeof duration === 'number' && duration > 0 ? duration : null;
}

function extractMode(raw: any): RoutingMode {
  const mode = (raw.mode || raw.type || raw.routeType || '').toLowerCase();
  if (['driving', 'walking', 'cycling'].includes(mode)) return mode as RoutingMode;
  return 'walking';
}

function extractSteps(raw: any): RouteStep[] | undefined {
  const steps = raw.steps || raw.legs?.[0]?.steps;
  if (!Array.isArray(steps)) return undefined;

  const extracted: RouteStep[] = [];

  for (const step of steps) {
    const geometry = extractGeometry(step);
    if (!geometry) continue;

    extracted.push({
      instruction: step.instruction || step.maneuver?.instruction || step.name || '',
      distance: step.distance || step.distances?.[0] || 0,
      duration: step.duration || step.durations?.[0] || 0,
      geometry,
      turnType: extractTurnType(step.maneuver),
      maneuver: step.maneuver?.type || undefined,
    });
  }

  return extracted.length > 0 ? extracted : undefined;
}

function extractTurnType(maneuver: unknown): RouteStep['turnType'] | undefined {
  if (!maneuver || typeof maneuver !== 'object') return undefined;

  const m = maneuver as Record<string, unknown>;
  const typeStr = m.type || m.modifier;
  const type = (typeof typeStr === 'string' ? typeStr : '').toLowerCase();

  const validTurns: RouteStep['turnType'][] = ['left', 'right', 'straight', 'sharp-left', 'sharp-right', 'u-turn'];
  if (validTurns.includes(type as RouteStep['turnType'])) {
    return type as RouteStep['turnType'];
  }

  return undefined;
}

function extractWaypoints(raw: any): Route['waypoints'] | undefined {
  const waypoints = raw.waypoints;
  if (!Array.isArray(waypoints)) return undefined;

  return waypoints
    .map((wp: any) => {
      const lat = typeof wp.lat === 'number' ? wp.lat : typeof wp.latitude === 'number' ? wp.latitude : null;
      const lng = typeof wp.lng === 'number' ? wp.lng : typeof wp.longitude === 'number' ? wp.longitude : null;

      if (typeof lat === 'number' && typeof lng === 'number') {
        return { lat, lng };
      }

      return null;
    })
    .filter((wp): wp is { lat: number; lng: number } => wp !== null);
}

function extractSummary(raw: any): string | null {
  const summary = raw.summary || raw.name || raw.instruction;
  return typeof summary === 'string' ? summary.trim() || null : null;
}

/**
 * Decode polyline string (Google polyline encoding format)
 */
function decodePolyline(polyline: string): [number, number][] {
  const coordinates: [number, number][] = [];
  let index = 0;
  let lat = 0;
  let lng = 0;

  while (index < polyline.length) {
    let result = 0;
    let shift = 0;

    let char: number;
    do {
      char = polyline.charCodeAt(index++) - 63;
      result |= (char & 0x1f) << shift;
      shift += 5;
    } while (char >= 0x20);

    const dlat = result & 1 ? ~(result >> 1) : result >> 1;
    lat += dlat;

    result = 0;
    shift = 0;

    do {
      char = polyline.charCodeAt(index++) - 63;
      result |= (char & 0x1f) << shift;
      shift += 5;
    } while (char >= 0x20);

    const dlng = result & 1 ? ~(result >> 1) : result >> 1;
    lng += dlng;

    coordinates.push([lng / 1e5, lat / 1e5]);
  }

  return coordinates;
}

/**
 * MapEntranceService — manage entrances for buildings/locations
 * 
 * Responsible for:
 * - Fetching entrances for a location
 * - Finding nearest entrance for routing
 * - Sorting entrances by priority
 * - Fallback generation when backend doesn't provide entrance data
 */

import { campusMap } from '@/lib/api/campus-map.api';
import { Entrance, sortEntrancesByPriority, hasEntranceCoordinates } from '../types/entrance';
import { Location } from '../types/location';
import {
  normalizeEntrance,
  normalizeEntrances,
  createFallbackEntrances,
} from '../normalizers/entranceNormalizer';
import { BaseMapService, MapServiceError } from './baseService';
import { haversineDistance, findNearest } from '../utils/distance';

/**
 * Entrance service singleton
 */
export class MapEntranceService extends BaseMapService {
  private static instance: MapEntranceService;

  private constructor() {
    super();
  }

  static getInstance(): MapEntranceService {
    if (!MapEntranceService.instance) {
      MapEntranceService.instance = new MapEntranceService();
    }
    return MapEntranceService.instance;
  }

  /**
   * Get all entrances for a location
   * Falls back to generated entrances from location tags if backend has no explicit entrances
   */
  async getEntrances(locationId: string, location?: Location): Promise<Entrance[]> {
    if (!locationId) {
      throw new MapServiceError('INVALID_ID', 'Location ID is required');
    }

    const cacheKey = `entrances:${locationId}`;

    // Check cache first
    const cached = this.getFromCache<Entrance[]>(cacheKey);
    if (cached) return cached;

    try {
      return await this.deduplicate(cacheKey, async () => {
        // Try fetching from backend
        const raw = await campusMap.getFeatureEntrances(locationId);
        const features = this.ensureArray(raw) as Array<Record<string, unknown>>;

        let entrances: Entrance[] = [];

        if (features.length > 0) {
          // Backend has explicit entrance data
          entrances = normalizeEntrances(features);
        } else if (location) {
          // No explicit entrances — create fallback from location tags
          entrances = createFallbackEntrances(location.name, location.id, location.tags);
        } else {
          // No data and no location object — return empty with warning
          console.warn(`No entrances found for location ${locationId} and no fallback location provided`);
          return [];
        }

        // Sort by priority (main entrance first)
        entrances = sortEntrancesByPriority(entrances);

        // Cache for 30 minutes
        this.setCache(cacheKey, entrances, 30 * 60 * 1000);

        return entrances;
      });
    } catch (error) {
      // Non-fatal — return fallback entrances if available
      if (location) {
        const fallback = createFallbackEntrances(location.name, location.id, location.tags);
        this.setCache(cacheKey, fallback, 10 * 60 * 1000);
        return fallback;
      }

      throw new MapServiceError(
        'ENTRANCE_FETCH_FAILED',
        `Failed to fetch entrances for location ${locationId}`,
        error as Error,
      );
    }
  }

  /**
   * Find the best entrance for navigation
   * Prioritizes: main entrance → accessible entrance → nearest entrance
   */
  async selectBestEntrance(
    locationId: string,
    location: Location,
    options?: {
      userLocation?: { lat: number; lng: number };
      preferAccessible?: boolean;
    },
  ): Promise<Entrance | null> {
    const entrances = await this.getEntrances(locationId, location);

    if (entrances.length === 0) return null;

    // Filter valid entrances (must have coordinates)
    const validEntrances = entrances.filter(hasEntranceCoordinates);
    if (validEntrances.length === 0) return null;

    // Priority 1: Accessible entrance if requested
    if (options?.preferAccessible) {
      const accessible = validEntrances.find(e => e.isAccessible);
      if (accessible) return accessible;
    }

    // Priority 2: Main entrance
    const main = validEntrances.find(e => e.kind === 'MAIN');
    if (main) return main;

    // Priority 3: Nearest to user if user location available
    if (options?.userLocation) {
      const entrancePoints = validEntrances.map(e => ({ ...e, lat: e.latitude, lng: e.longitude }));
      const nearest = findNearest(options.userLocation, entrancePoints);
      if (nearest) {
        return validEntrances.find(e => e.id === nearest.point.id) || null;
      }
    }

    // Fallback: First valid entrance
    return validEntrances[0];
  }

  /**
   * Find nearest entrance across all locations
   */
  findNearestEntrance(
    userLocation: { lat: number; lng: number },
    entrances: Entrance[],
  ): { entrance: Entrance; distance: number } | null {
    const validEntrances = entrances.filter(hasEntranceCoordinates);
    if (validEntrances.length === 0) return null;

    const entrancePoints = validEntrances.map(e => ({ ...e, lat: e.latitude, lng: e.longitude }));
    const nearest = findNearest(userLocation, entrancePoints);
    if (!nearest) return null;

    const entrance = validEntrances.find(e => e.id === nearest.point.id);
    if (!entrance) return null;

    return {
      entrance,
      distance: nearest.distance,
    };
  }

  /**
   * Get entrance with minimum distance to user
   */
  getClosestEntrance(
    entrances: Entrance[],
    userLocation: { lat: number; lng: number },
  ): Entrance | null {
    const validEntrances = entrances.filter(hasEntranceCoordinates);
    if (validEntrances.length === 0) return null;

    let closest = validEntrances[0];
    let minDistance = haversineDistance(userLocation, { lat: closest.latitude, lng: closest.longitude });

    for (const entrance of validEntrances.slice(1)) {
      const distance = haversineDistance(userLocation, { lat: entrance.latitude, lng: entrance.longitude });
      if (distance < minDistance) {
        minDistance = distance;
        closest = entrance;
      }
    }

    return closest;
  }

  /**
   * Invalidate entrance caches (call when admin updates entrances)
   */
  invalidateEntranceCache(locationId?: string): void {
    if (locationId) {
      this.invalidateCache(`entrances:${locationId}`);
    } else {
      this.clearCachePattern(/^entrances:/);
    }
  }

  // ─── Helpers ────────────────────────────────────────────────────────────────

  private ensureArray(data: unknown): unknown[] {
    if (Array.isArray(data)) return data;
    if (data && typeof data === 'object') {
      const obj = data as Record<string, unknown>;
      if (Array.isArray(obj.features)) return obj.features;
      if (Array.isArray(obj.entrances)) return obj.entrances;
      if (Array.isArray(obj.data)) return obj.data;
    }
    return [];
  }
}

/**
 * Export singleton instance
 */
export const mapEntranceService = MapEntranceService.getInstance();

/**
 * MapLocationService — manage locations/features on the campus map
 * 
 * Responsible for:
 * - Fetching location lists with filtering
 * - Getting individual location details
 * - Searching locations
 * - Finding nearest locations
 * - Caching and deduplication
 */

import { campusMap } from '@/lib/api/campus-map.api';
import { Location, MapLocation, isMapLocation, LocationType } from '../types/location';
import { normalizeLocation, normalizeLocations } from '../normalizers/locationNormalizer';
import { BaseMapService, MapServiceError } from './baseService';
import { haversineDistance } from '../utils/distance';

export interface LocationListOptions {
  category?: LocationType;
  limit?: number;
  bbox?: { minLng: number; maxLng: number; minLat: number; maxLat: number };
}

export interface LocationSearchOptions {
  query: string;
  category?: LocationType;
  userLocation?: { lat: number; lng: number };
  limit?: number;
}

export interface NearestLocationsOptions {
  userLocation: { lat: number; lng: number };
  category?: LocationType;
  radiusMeters?: number;
  limit?: number;
}

/**
 * Location service singleton
 */
export class MapLocationService extends BaseMapService {
  private static instance: MapLocationService;

  private constructor() {
    super();
  }

  static getInstance(): MapLocationService {
    if (!MapLocationService.instance) {
      MapLocationService.instance = new MapLocationService();
    }
    return MapLocationService.instance;
  }

  /**
   * Get all locations, optionally filtered by category
   */
  async getLocations(options?: LocationListOptions): Promise<Location[]> {
    const cacheKey = `locations:${options?.category || 'all'}`;

    // Check cache first
    const cached = this.getFromCache<Location[]>(cacheKey);
    if (cached) return cached;

    try {
      return await this.deduplicate(cacheKey, async () => {
        const params: Record<string, string> = {};
        if (options?.category) params.category = options.category;
        if (options?.limit) params.limit = String(options.limit);

        const raw = await campusMap.getFeatures(params);
        const normalized = normalizeLocations(this.ensureArray(raw) as Record<string, unknown>[]);

        // Cache for 10 minutes
        this.setCache(cacheKey, normalized, 10 * 60 * 1000);

        return normalized;
      });
    } catch (error) {
      throw new MapServiceError(
        'LOCATION_LIST_FAILED',
        'Failed to fetch locations',
        error as Error,
      );
    }
  }

  /**
   * Get a single location by ID
   */
  async getLocation(id: string): Promise<Location | null> {
    if (!id) {
      throw new MapServiceError('INVALID_ID', 'Location ID is required');
    }

    const cacheKey = `location:${id}`;

    // Check cache first
    const cached = this.getFromCache<Location | null>(cacheKey);
    if (cached !== null && cached !== undefined) return cached;

    try {
      return await this.deduplicate(cacheKey, async () => {
        const raw = await campusMap.getFeature(id);
        const normalized = normalizeLocation(raw as any);

        // Cache for 30 minutes
        if (normalized) {
          this.setCache(cacheKey, normalized, 30 * 60 * 1000);
        }

        return normalized;
      });
    } catch (error) {
      throw new MapServiceError(
        'LOCATION_DETAIL_FAILED',
        `Failed to fetch location ${id}`,
        error as Error,
      );
    }
  }

  /**
   * Search locations by query string
   */
  async searchLocations(options: LocationSearchOptions): Promise<Location[]> {
    const { query, category, userLocation, limit } = options;

    if (!query || query.trim().length === 0) {
      throw new MapServiceError('INVALID_QUERY', 'Search query is required');
    }

    const cacheKey = `search:${query}:${category || 'all'}:${userLocation ? `${userLocation.lat},${userLocation.lng}` : 'no-location'}`;

    // Check cache first (shorter TTL for search results)
    const cached = this.getFromCache<Location[]>(cacheKey);
    if (cached) return cached;

    try {
      return await this.deduplicate(cacheKey, async () => {
        const near = userLocation ? `${userLocation.lat},${userLocation.lng}` : undefined;

        const raw = await campusMap.search({
          query,
          category,
          near,
        } as any);

        let normalized = normalizeLocations(this.ensureArray(raw) as Record<string, unknown>[]);

        // Apply limit if specified
        if (limit && normalized.length > limit) {
          normalized = normalized.slice(0, limit);
        }

        // Cache for 5 minutes
        this.setCache(cacheKey, normalized, 5 * 60 * 1000);

        return normalized;
      });
    } catch (error) {
      throw new MapServiceError(
        'LOCATION_SEARCH_FAILED',
        'Failed to search locations',
        error as Error,
      );
    }
  }

  /**
   * Get nearest locations to user
   * Server computes distances for accuracy
   */
  async getNearestLocations(options: NearestLocationsOptions): Promise<Location[]> {
    const { userLocation, category, radiusMeters, limit } = options;

    const cacheKey = `nearest:${userLocation.lat},${userLocation.lng}:${category || 'all'}`;

    // Check cache first
    const cached = this.getFromCache<Location[]>(cacheKey);
    if (cached) return cached;

    try {
      return await this.deduplicate(cacheKey, async () => {
        const raw = await campusMap.getNearest(
          userLocation.lat,
          userLocation.lng,
          category,
        );

        let normalized = normalizeLocations(this.ensureArray(raw) as Record<string, unknown>[]);

        // Filter by radius if specified
        if (radiusMeters) {
          normalized = normalized.filter(loc => {
            if (!isMapLocation(loc)) return false;
            const distance = haversineDistance(userLocation, { lat: loc.latitude, lng: loc.longitude });
            return distance <= radiusMeters;
          });
        }

        // Apply limit if specified
        if (limit && normalized.length > limit) {
          normalized = normalized.slice(0, limit);
        }

        // Cache for 2 minutes (nearest results change as user moves)
        this.setCache(cacheKey, normalized, 2 * 60 * 1000);

        return normalized;
      });
    } catch (error) {
      throw new MapServiceError(
        'NEAREST_LOCATION_FAILED',
        'Failed to fetch nearest locations',
        error as Error,
      );
    }
  }

  /**
   * Filter locations by mapability (have valid coordinates)
   */
  filterMapLocations(locations: Location[]): MapLocation[] {
    return locations.filter(isMapLocation);
  }

  /**
   * Sort locations by distance from a point
   */
  sortByDistance(locations: Location[], center: { lat: number; lng: number }): Location[] {
    return [...locations].sort((a, b) => {
      const distA = isMapLocation(a) ? haversineDistance(center, { lat: a.latitude, lng: a.longitude }) : Infinity;
      const distB = isMapLocation(b) ? haversineDistance(center, { lat: b.latitude, lng: b.longitude }) : Infinity;
      return distA - distB;
    });
  }

  /**
   * Invalidate location caches (call this after admin creates/updates locations)
   */
  invalidateLocationCache(): void {
    this.clearCachePattern(/^(locations|location|search|nearest):/);
  }

  // ─── Helpers ────────────────────────────────────────────────────────────────

  private ensureArray(data: unknown): unknown[] {
    if (Array.isArray(data)) return data;
    if (data && typeof data === 'object') {
      const obj = data as Record<string, unknown>;
      if (Array.isArray(obj.features)) return obj.features;
      if (Array.isArray(obj.locations)) return obj.locations;
      if (Array.isArray(obj.data)) return obj.data;
    }
    return [];
  }
}

