/**
 * Bounding box and geographic boundary utilities
 */

import { MapBounds } from '../types/map';

export interface BoundingBox {
  minLng: number;
  maxLng: number;
  minLat: number;
  maxLat: number;
}

/**
 * Create a bounding box from an array of points
 */
export function calculateBounds(points: Array<{ lat: number; lng: number }>): BoundingBox | null {
  if (points.length === 0) return null;

  let minLat = points[0].lat;
  let maxLat = points[0].lat;
  let minLng = points[0].lng;
  let maxLng = points[0].lng;

  for (const point of points) {
    minLat = Math.min(minLat, point.lat);
    maxLat = Math.max(maxLat, point.lat);
    minLng = Math.min(minLng, point.lng);
    maxLng = Math.max(maxLng, point.lng);
  }

  return { minLat, maxLat, minLng, maxLng };
}

/**
 * Expand bounds by a padding distance (in degrees)
 * Rule of thumb: 1 degree ≈ 111 km
 * 
 * @param bounds - Original bounds
 * @param paddingDegrees - Padding in decimal degrees
 */
export function expandBounds(bounds: BoundingBox, paddingDegrees: number): BoundingBox {
  return {
    minLat: bounds.minLat - paddingDegrees,
    maxLat: bounds.maxLat + paddingDegrees,
    minLng: bounds.minLng - paddingDegrees,
    maxLng: bounds.maxLng + paddingDegrees,
  };
}

/**
 * Convert bounding box to MapLibre LngLatBounds format
 * MapLibre expects: [[minLng, minLat], [maxLng, maxLat]]
 */
export function boundsToLngLatArray(bounds: BoundingBox): [[number, number], [number, number]] {
  return [
    [bounds.minLng, bounds.minLat],
    [bounds.maxLng, bounds.maxLat],
  ];
}

/**
 * Check if a point is within bounds
 */
export function isPointInBounds(point: { lat: number; lng: number }, bounds: BoundingBox): boolean {
  return (
    point.lat >= bounds.minLat &&
    point.lat <= bounds.maxLat &&
    point.lng >= bounds.minLng &&
    point.lng <= bounds.maxLng
  );
}

/**
 * Calculate center of bounds
 */
export function boundsCentre(bounds: BoundingBox): { lat: number; lng: number } {
  return {
    lat: (bounds.minLat + bounds.maxLat) / 2,
    lng: (bounds.minLng + bounds.maxLng) / 2,
  };
}

/**
 * Calculate approximate zoom level based on bounds width
 * 
 * Rough guide:
 * - 360° → zoom 0
 * - 180° → zoom 1
 * - 90° → zoom 2
 * - etc.
 */
export function calculateZoomForBounds(bounds: BoundingBox): number {
  const lngDiff = bounds.maxLng - bounds.minLng;
  return Math.floor(Math.log2(360 / lngDiff)) - 1;
}

/**
 * Constrain point within bounds
 */
export function constrainPointToBounds(
  point: { lat: number; lng: number },
  bounds: BoundingBox,
): { lat: number; lng: number } {
  return {
    lat: Math.max(bounds.minLat, Math.min(bounds.maxLat, point.lat)),
    lng: Math.max(bounds.minLng, Math.min(bounds.maxLng, point.lng)),
  };
}

/**
 * Create a bounding box for a circle (approximation)
 * 
 * @param center - Center point
 * @param radiusMeters - Radius in meters
 */
export function circleToBounds(center: { lat: number; lng: number }, radiusMeters: number): BoundingBox {
  // Rough approximation: 1 degree ≈ 111 km
  const radiusDegrees = radiusMeters / (111 * 1000);

  return {
    minLat: center.lat - radiusDegrees,
    maxLat: center.lat + radiusDegrees,
    minLng: center.lng - radiusDegrees,
    maxLng: center.lng + radiusDegrees,
  };
}

/**
 * Merge multiple bounding boxes into one larger box
 */
export function mergeBounds(boundingBoxes: BoundingBox[]): BoundingBox | null {
  if (boundingBoxes.length === 0) return null;

  let minLat = boundingBoxes[0].minLat;
  let maxLat = boundingBoxes[0].maxLat;
  let minLng = boundingBoxes[0].minLng;
  let maxLng = boundingBoxes[0].maxLng;

  for (const box of boundingBoxes.slice(1)) {
    minLat = Math.min(minLat, box.minLat);
    maxLat = Math.max(maxLat, box.maxLat);
    minLng = Math.min(minLng, box.minLng);
    maxLng = Math.max(maxLng, box.maxLng);
  }

  return { minLat, maxLat, minLng, maxLng };
}

/**
 * GeoJSON and geometry utilities
 */

import { GeoJSONGeometry, GeoJSONLineString, GeoJSONPolygon } from '../types/geojson';

/**
 * Calculate length of a LineString in meters
 */
export function lineStringLength(lineString: GeoJSONLineString): number {
  if (lineString.coordinates.length < 2) return 0;

  let length = 0;
  for (let i = 0; i < lineString.coordinates.length - 1; i++) {
    const [lng1, lat1] = lineString.coordinates[i];
    const [lng2, lat2] = lineString.coordinates[i + 1];
    length += haversineDistance(lat1, lng1, lat2, lng2);
  }

  return length;
}

/**
 * Calculate area of a Polygon in square meters
 * Using the Shoelace formula projected to equirectangular
 */
export function polygonArea(polygon: GeoJSONPolygon): number {
  if (polygon.coordinates.length === 0) return 0;

  let area = 0;
  const [outerRing] = polygon.coordinates;

  // Shoelace formula
  for (let i = 0; i < outerRing.length - 1; i++) {
    const [lng1, lat1] = outerRing[i];
    const [lng2, lat2] = outerRing[i + 1];
    area += (lng2 - lng1) * (lat2 + lat1);
  }

  // Convert from degrees² to meters² (very rough approximation)
  const latRadians = (outerRing[0][1] * Math.PI) / 180;
  const metersPerDegreeLng = 111320 * Math.cos(latRadians);
  const metersPerDegreeLat = 111320;

  return Math.abs(area * metersPerDegreeLng * metersPerDegreeLat) / 2;
}

/**
 * Check if a point is inside a polygon (ray casting algorithm)
 */
export function isPointInPolygon(
  point: { lat: number; lng: number },
  polygon: GeoJSONPolygon,
): boolean {
  const [lng, lat] = [point.lng, point.lat];
  const [outerRing] = polygon.coordinates;

  let isInside = false;
  let j = outerRing.length - 1;

  for (let i = 0; i < outerRing.length; i++) {
    const xi = outerRing[i][0];
    const yi = outerRing[i][1];
    const xj = outerRing[j][0];
    const yj = outerRing[j][1];

    const intersect = yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (intersect) isInside = !isInside;

    j = i;
  }

  return isInside;
}

/**
 * Get the center of a polygon
 */
export function polygonCenter(polygon: GeoJSONPolygon): { lat: number; lng: number } | null {
  const [outerRing] = polygon.coordinates;
  if (outerRing.length === 0) return null;

  let sumLng = 0;
  let sumLat = 0;

  for (const [lng, lat] of outerRing) {
    sumLng += lng;
    sumLat += lat;
  }

  return {
    lng: sumLng / outerRing.length,
    lat: sumLat / outerRing.length,
  };
}

/**
 * Simplify a line string using the Ramer-Douglas-Peucker algorithm
 * Reduces number of points while maintaining general shape
 */
export function simplifyLineString(
  lineString: GeoJSONLineString,
  tolerance: number = 0.0001, // in decimal degrees (~10 meters)
): GeoJSONLineString {
  if (lineString.coordinates.length <= 2) return lineString;

  const pointsOnly = lineString.coordinates.map(pos => [pos[0], pos[1]] as [number, number]);
  const simplified = rdpSimplify(pointsOnly, tolerance);

  return {
    type: 'LineString',
    coordinates: simplified as GeoJSONLineString['coordinates'],
  };
}

/**
 * Ramer-Douglas-Peucker implementation
 */
function rdpSimplify(points: [number, number][], tolerance: number): [number, number][] {
  if (points.length < 3) return points;

  const start = points[0];
  const end = points[points.length - 1];

  let maxDist = 0;
  let maxIndex = 0;

  for (let i = 1; i < points.length - 1; i++) {
    const dist = perpendicularDistance(points[i], start, end);
    if (dist > maxDist) {
      maxDist = dist;
      maxIndex = i;
    }
  }

  if (maxDist > tolerance) {
    const left = rdpSimplify(points.slice(0, maxIndex + 1), tolerance);
    const right = rdpSimplify(points.slice(maxIndex), tolerance);
    return [...left.slice(0, -1), ...right];
  }

  return [start, end];
}

/**
 * Calculate perpendicular distance from a point to a line
 */
function perpendicularDistance(point: [number, number], lineStart: [number, number], lineEnd: [number, number]): number {
  const [px, py] = point;
  const [x1, y1] = lineStart;
  const [x2, y2] = lineEnd;

  const num = Math.abs((y2 - y1) * px - (x2 - x1) * py + x2 * y1 - y2 * x1);
  const den = Math.sqrt(Math.pow(y2 - y1, 2) + Math.pow(x2 - x1, 2));

  return den === 0 ? 0 : num / den;
}

// ─── Helper ────────────────────────────────────────────────────────────────────

/**
 * Haversine distance in meters
 */
function haversineDistance(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const R = 6_371_000;
  const φ1 = (lat1 * Math.PI) / 180;
  const φ2 = (lat2 * Math.PI) / 180;
  const Δφ = ((lat2 - lat1) * Math.PI) / 180;
  const Δλ = ((lng2 - lng1) * Math.PI) / 180;

  const a = Math.sin(Δφ / 2) ** 2 + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
}

/**
 * Layer Manager — Centralized MapLibre layer and source management
 * 
 * Handles:
 * - Layer initialization and cleanup
 * - Dynamic layer visibility toggling
 * - Layer state management (paint properties, visibility)
 * - Performance optimization (layer batching)
 */

import maplibregl from 'maplibre-gl';

export interface LayerConfig {
  id: string;
  type: 'circle' | 'line' | 'fill' | 'symbol';
  source: string;
  sourceData?: any;
  filter?: any[];
  paint?: Record<string, any>;
  layout?: Record<string, any>;
  minzoom?: number;
  maxzoom?: number;
  beforeId?: string; // Insert before this layer for z-ordering
}

export interface SourceConfig {
  id: string;
  type: 'geojson' | 'vector' | 'raster';
  data?: any;
  url?: string;
}

export class LayerManager {
  private map: maplibregl.Map;
  private layers: Map<string, LayerConfig> = new Map();
  private sources: Map<string, SourceConfig> = new Map();
  private layerVisibility: Map<string, boolean> = new Map();

  constructor(map: maplibregl.Map) {
    this.map = map;
  }

  /**
   * Add a source to the map
   */
  addSource(config: SourceConfig): void {
    if (this.map.getSource(config.id)) {
      console.warn(`Source ${config.id} already exists`);
      return;
    }

    this.sources.set(config.id, config);

    this.map.addSource(config.id, {
      type: config.type,
      data: config.data || config.url,
    } as any);
  }

  /**
   * Update source data (for GeoJSON sources)
   */
  updateSourceData(sourceId: string, data: any): void {
    const source = this.map.getSource(sourceId) as maplibregl.GeoJSONSource;
    if (source && 'setData' in source) {
      source.setData(data);
    }
  }

  /**
   * Remove a source
   */
  removeSource(sourceId: string): void {
    const source = this.map.getSource(sourceId);
    if (!source) return;

    // Remove all layers using this source
    const layersToRemove = Array.from(this.layers.values())
      .filter(layer => layer.source === sourceId)
      .map(layer => layer.id);

    layersToRemove.forEach(layerId => this.removeLayer(layerId));

    this.map.removeSource(sourceId);
    this.sources.delete(sourceId);
  }

  /**
   * Add a layer to the map
   */
  addLayer(config: LayerConfig): void {
    if (this.map.getLayer(config.id)) {
      console.warn(`Layer ${config.id} already exists`);
      return;
    }

    this.layers.set(config.id, config);
    this.layerVisibility.set(config.id, true);

    const layerDef: any = {
      id: config.id,
      type: config.type,
      source: config.source,
      paint: config.paint || {},
      layout: config.layout || {},
    };

    if (config.filter !== undefined) layerDef.filter = config.filter;
    if (config.minzoom !== undefined) layerDef.minzoom = config.minzoom;
    if (config.maxzoom !== undefined) layerDef.maxzoom = config.maxzoom;

    this.map.addLayer(layerDef, config.beforeId);
  }

  /**
   * Update layer paint properties
   */
  updateLayerPaint(layerId: string, paint: Record<string, any>): void {
    const layer = this.layers.get(layerId);
    if (!layer) return;

    Object.entries(paint).forEach(([key, value]) => {
      this.map.setPaintProperty(layerId, key, value);
      if (layer.paint) {
        layer.paint[key] = value;
      }
    });
  }

  /**
   * Update layer layout properties
   */
  updateLayerLayout(layerId: string, layout: Record<string, any>): void {
    const layer = this.layers.get(layerId);
    if (!layer) return;

    Object.entries(layout).forEach(([key, value]) => {
      this.map.setLayoutProperty(layerId, key, value);
      if (layer.layout) {
        layer.layout[key] = value;
      }
    });
  }

  /**
   * Toggle layer visibility
   */
  setLayerVisibility(layerId: string, visible: boolean): void {
    if (!this.map.getLayer(layerId)) return;

    this.map.setLayoutProperty(layerId, 'visibility', visible ? 'visible' : 'none');
    this.layerVisibility.set(layerId, visible);
  }

  /**
   * Get layer visibility
   */
  getLayerVisibility(layerId: string): boolean {
    return this.layerVisibility.get(layerId) ?? false;
  }

  /**
   * Toggle multiple layers at once
   */
  setLayersVisibility(layerIds: string[], visible: boolean): void {
    layerIds.forEach(id => this.setLayerVisibility(id, visible));
  }

  /**
   * Remove a layer
   */
  removeLayer(layerId: string): void {
    const layer = this.map.getLayer(layerId);
    if (!layer) return;

    this.map.removeLayer(layerId);
    this.layers.delete(layerId);
    this.layerVisibility.delete(layerId);
  }

  /**
   * Get all layer IDs
   */
  getLayerIds(): string[] {
    return Array.from(this.layers.keys());
  }

  /**
   * Set layer opacity
   */
  setLayerOpacity(layerId: string, opacity: number): void {
    const layer = this.map.getLayer(layerId);
    if (!layer) return;

    const paintKey = layer.type === 'line'
      ? 'line-opacity'
      : layer.type === 'fill'
        ? 'fill-opacity'
        : layer.type === 'circle'
          ? 'circle-opacity'
          : 'text-opacity';

    this.map.setPaintProperty(layerId, paintKey, opacity);
  }

  /**
   * Cleanup — remove all layers and sources
   */
  cleanup(): void {
    // Remove layers in reverse order (top to bottom)
    const layerIds = Array.from(this.layers.keys()).reverse();
    layerIds.forEach(id => this.removeLayer(id));

    // Remove sources
    const sourceIds = Array.from(this.sources.keys());
    sourceIds.forEach(id => this.removeSource(id));

    this.layers.clear();
    this.sources.clear();
    this.layerVisibility.clear();
  }
}

export default LayerManager;

