/**
 * Validator function type
 */
export type FieldValidator = (value: any) => string | undefined;

/**
 * Validates that a field value is not empty.
 *
 * Can be used in two ways:
 *   1. As a factory (curried): `validateRequired('FieldName')` → returns a FieldValidator
 *   2. As a direct call:       `validateRequired(value, 'FieldName')` → returns string | undefined
 *
 * @example
 * // Factory usage (for schemas / composeValidators)
 * composeValidators(validateRequired('Email'), validateMinLength(5, 'Email'))
 *
 * // Direct usage
 * const error = validateRequired(email, 'Email');
 */
export function validateRequired(fieldName?: string): FieldValidator;
export function validateRequired(value: any, fieldName?: string): string | undefined;
export function validateRequired(
  valueOrFieldName?: any,
  fieldName?: string,
): FieldValidator | string | undefined {
  // Called as factory: validateRequired('FieldName') or validateRequired()
  // Detect factory call: single arg that is a string (treated as fieldName), or no args
  if (fieldName === undefined && (valueOrFieldName === undefined || typeof valueOrFieldName === 'string')) {
    const name = valueOrFieldName ?? 'Field';
    return (value: any): string | undefined => {
      if (value === null || value === undefined || value === '') {
        return `${name} is required`;
      }
      return undefined;
    };
  }
  // Called directly: validateRequired(value, 'FieldName')
  const name = fieldName ?? 'Field';
  const value = valueOrFieldName;
  if (value === null || value === undefined || value === '') {
    return `${name} is required`;
  }
  return undefined;
}

/**
 * Validates that a string meets minimum length requirement
 *
 * @param minLength - Minimum required length
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateMinLength(8, 'Password');
 * const error = validator('short');
 * if (error) console.log(error); // "Password must be at least 8 characters long"
 */
export function validateMinLength(
  minLength: number,
  fieldName: string = 'Field'
): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined) {
      return undefined; // Let validateRequired handle empty values
    }
    const stringValue = String(value);
    if (stringValue.length < minLength) {
      return `${fieldName} must be at least ${minLength} characters long`;
    }
    return undefined;
  };
}

/**
 * Validates that a string meets maximum length requirement
 *
 * @param maxLength - Maximum allowed length
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateMaxLength(50, 'Username');
 * const error = validator('a'.repeat(51));
 * if (error) console.log(error); // "Username must be no more than 50 characters long"
 */
export function validateMaxLength(
  maxLength: number,
  fieldName: string = 'Field'
): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined) {
      return undefined;
    }
    const stringValue = String(value);
    if (stringValue.length > maxLength) {
      return `${fieldName} must be no more than ${maxLength} characters long`;
    }
    return undefined;
  };
}

/**
 * Validates that a value matches a regex pattern
 *
 * @param pattern - Regex pattern to match
 * @param fieldName - Optional name of the field for error message
 * @param message - Optional custom error message
 * @returns Validator function
 *
 * @example
 * const validator = validatePattern(/^[a-z]+$/, 'Username', 'Username must contain only lowercase letters');
 * const error = validator('invalid123');
 * if (error) console.log(error);
 */
export function validatePattern(
  pattern: RegExp,
  fieldName: string = 'Field',
  message?: string
): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    const stringValue = String(value);
    if (!pattern.test(stringValue)) {
      return message || `${fieldName} format is invalid`;
    }
    return undefined;
  };
}

/**
 * Validates that a value is in a list of allowed values
 *
 * @param allowedValues - Array of allowed values
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateOneOf(['admin', 'user', 'guest'], 'Role');
 * const error = validator('invalid');
 * if (error) console.log(error); // "Role must be one of: admin, user, guest"
 */
export function validateOneOf(
  allowedValues: any[],
  fieldName: string = 'Field'
): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined) {
      return undefined;
    }
    if (!allowedValues.includes(value)) {
      return `${fieldName} must be one of: ${allowedValues.join(', ')}`;
    }
    return undefined;
  };
}

/**
 * Validates that a value is a valid number
 *
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateNumber('Age');
 * const error = validator('abc');
 * if (error) console.log(error); // "Age must be a valid number"
 */
export function validateNumber(fieldName: string = 'Field'): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    const num = Number(value);
    if (isNaN(num)) {
      return `${fieldName} must be a valid number`;
    }
    return undefined;
  };
}

/**
 * Validates that a number is within a range
 *
 * @param min - Minimum allowed value
 * @param max - Maximum allowed value
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateRange(0, 100, 'Score');
 * const error = validator(150);
 * if (error) console.log(error); // "Score must be between 0 and 100"
 */
export function validateRange(
  min: number,
  max: number,
  fieldName: string = 'Field'
): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    const num = Number(value);
    if (isNaN(num)) {
      return `${fieldName} must be a valid number`;
    }
    if (num < min || num > max) {
      return `${fieldName} must be between ${min} and ${max}`;
    }
    return undefined;
  };
}

/**
 * Validates that two values match (e.g., password confirmation)
 *
 * @param compareValue - Value to compare against
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateMatches(password, 'Confirm Password');
 * const error = validator(confirmPassword);
 * if (error) console.log(error); // "Confirm Password must match Password"
 */
export function validateMatches(
  compareValue: any,
  fieldName: string = 'Field'
): FieldValidator {
  return (value: any): string | undefined => {
    if (value !== compareValue) {
      return `${fieldName} must match`;
    }
    return undefined;
  };
}

/**
 * Validates that a string contains only alphanumeric characters
 *
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateAlphanumeric('Username');
 * const error = validator('user@123');
 * if (error) console.log(error); // "Username must contain only alphanumeric characters"
 */
export function validateAlphanumeric(fieldName: string = 'Field'): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    const stringValue = String(value);
    if (!/^[a-zA-Z0-9]+$/.test(stringValue)) {
      return `${fieldName} must contain only alphanumeric characters`;
    }
    return undefined;
  };
}

/**
 * Validates that a value is a valid URL
 *
 * @param fieldName - Optional name of the field for error message
 * @returns Validator function
 *
 * @example
 * const validator = validateUrl('Website');
 * const error = validator('not-a-url');
 * if (error) console.log(error); // "Website must be a valid URL"
 */
export function validateUrl(fieldName: string = 'Field'): FieldValidator {
  return (value: any): string | undefined => {
    if (value === null || value === undefined || value === '') {
      return undefined;
    }
    try {
      new URL(String(value));
      return undefined;
    } catch {
      return `${fieldName} must be a valid URL`;
    }
  };
}

/**
 * Composes multiple validators into a single validator
 * Returns error from first validator that fails
 *
 * @param validators - Array of validator functions to compose
 * @returns Combined validator function
 *
 * @example
 * const validator = composeValidators(
 *   validateRequired('Email'),
 *   validateMinLength(5, 'Email'),
 *   validateEmail
 * );
 * const error = validator(email);
 */
export function composeValidators(...validators: FieldValidator[]): FieldValidator {
  return (value: any): string | undefined => {
    for (const validator of validators) {
      const error = validator(value);
      if (error) {
        return error;
      }
    }
    return undefined;
  };
}

import { FormErrors } from '@/types/auth';
import { FieldValidator } from './fields';

/**
 * A relaxed validator type that also covers validators returning rich result
 * objects (e.g. validateEmail → ValidationResult, validatePassword →
 * PasswordValidationResult).  The form runner only uses the string-returning
 * subset at runtime, but this type lets tests and callers pass any callable
 * without casting.
 */
type AnyValidator = (value: any) => any;

/**
 * Validation schema for form fields
 * Maps field names to validator functions
 */
export type FormValidationSchema<T extends Record<string, any>> = {
  [K in keyof T]?: FieldValidator | AnyValidator | (FieldValidator | AnyValidator)[];
};

/**
 * Validates multiple form fields at once using a validation schema
 * Returns an object with field names as keys and error messages as values
 *
 * @param values - Form values object to validate
 * @param schema - Validation schema mapping fields to validators
 * @returns Object with field names and error messages (empty if all valid)
 *
 * @example
 * const schema = {
 *   email: validateEmail,
 *   password: validatePassword,
 *   username: [
 *     validateRequired,
 *     validateMinLength(3, 'Username'),
 *   ]
 * };
 * const errors = validateForm(formValues, schema);
 * if (Object.keys(errors).length > 0) {
 *   console.log(errors); // { username: "Username must be at least 3 characters long" }
 * }
 */
export function validateForm<T extends Record<string, any>>(
  values: T,
  schema: FormValidationSchema<T>
): Partial<FormErrors> {
  const errors: Partial<FormErrors> = {};

  for (const fieldName in schema) {
    const validators = schema[fieldName];
    if (!validators) continue;

    const fieldValue = values[fieldName];
    const validatorArray = Array.isArray(validators) ? validators : [validators];

    // Run all validators for this field
    for (const validator of validatorArray) {
      const error = validator(fieldValue);
      if (error) {
        errors[fieldName] = error;
        break; // Stop at first error for this field
      }
    }
  }

  return errors;
}

/**
 * Creates a reusable form validator function from a schema
 * Useful when the same validation rules are used in multiple places
 *
 * @param schema - Validation schema
 * @returns Function that validates values and returns errors
 *
 * @example
 * const validator = createFormValidator({
 *   email: validateEmail,
 *   password: validatePassword,
 * });
 *
 * const errors = validator(formValues);
 */
export function createFormValidator<T extends Record<string, any>>(
  schema: FormValidationSchema<T>
) {
  return (values: T): Partial<FormErrors> => validateForm(values, schema);
}

/**
 * Validates only specific fields from a form
 * Useful when you want to validate a subset of fields
 *
 * @param values - Form values object
 * @param schema - Validation schema
 * @param fieldNames - Array of field names to validate (if not provided, validates all)
 * @returns Object with errors only for specified fields
 *
 * @example
 * const errors = validateFormFields(formValues, schema, ['email', 'password']);
 */
export function validateFormFields<T extends Record<string, any>>(
  values: T,
  schema: FormValidationSchema<T>,
  fieldNames?: (keyof T)[]
): Partial<FormErrors> {
  const fieldsToValidate = fieldNames
    ? fieldNames.reduce((acc, field) => ({ ...acc, [field]: schema[field] }), {} as FormValidationSchema<T>)
    : schema;

  return validateForm(values, fieldsToValidate);
}

/**
 * Checks if a form has any validation errors
 *
 * @param errors - Errors object from validateForm
 * @returns true if there are any errors, false otherwise
 *
 * @example
 * const errors = validateForm(values, schema);
 * if (hasFormErrors(errors)) {
 *   console.log('Form has errors');
 * }
 */
export function hasFormErrors(errors: Partial<FormErrors>): boolean {
  return Object.values(errors).some((error) => error !== undefined && error !== '');
}

/**
 * Gets the count of validation errors in a form
 *
 * @param errors - Errors object from validateForm
 * @returns Number of fields with errors
 *
 * @example
 * const errorCount = getFormErrorCount(errors);
 * console.log(`${errorCount} fields have errors`);
 */
export function getFormErrorCount(errors: Partial<FormErrors>): number {
  return Object.values(errors).filter((error) => error !== undefined && error !== '').length;
}

/**
 * Clears errors for specific fields
 *
 * @param errors - Current errors object
 * @param fieldNames - Array of field names to clear errors for
 * @returns New errors object with cleared fields
 *
 * @example
 * const clearedErrors = clearFormFieldErrors(errors, ['email', 'password']);
 */
export function clearFormFieldErrors(
  errors: Partial<FormErrors>,
  fieldNames: string[]
): Partial<FormErrors> {
  const result = { ...errors };
  fieldNames.forEach((field) => {
    delete result[field];
  });
  return result;
}

/**
 * Merges multiple validation schemas.
 * Later schemas override earlier ones for the same fields.
 * Accepts schemas with different field-type parameters so heterogeneous
 * schemas can be combined without requiring a common generic type.
 *
 * @param schemas - Array of validation schemas to merge
 * @returns Merged validation schema
 *
 * @example
 * const baseSchema = { email: validateEmail };
 * const additionalSchema = { password: validatePassword };
 * const merged = mergeValidationSchemas(baseSchema, additionalSchema);
 */
export function mergeValidationSchemas<T extends Record<string, any>>(
  ...schemas: FormValidationSchema<any>[]
): FormValidationSchema<T> {
  return schemas.reduce((acc, schema) => ({ ...acc, ...schema }), {} as FormValidationSchema<T>);
}

/**
 * Result of password validation including strength assessment
 */
export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
  strength: 'weak' | 'fair' | 'good' | 'strong';
}

/**
 * Options for password validation
 */
export interface PasswordValidationOptions {
  minLength?: number;
  requireUppercase?: boolean;
  requireLowercase?: boolean;
  requireNumbers?: boolean;
  requireSpecialChars?: boolean;
}

/**
 * Validates a password against security requirements and calculates strength.
 * Default requirements: min 8 chars, 1 uppercase, 1 lowercase, 1 number, 1 special char
 *
 * @param password - The password to validate
 * @param options - Optional validation options (defaults to standard security requirements)
 * @returns PasswordValidationResult with validation status, list of errors, and strength rating
 *
 * @example
 * const result = validatePassword('MyPass123!');
 * if (!result.valid) {
 *   result.errors.forEach(error => console.log(error));
 * }
 * console.log(`Strength: ${result.strength}`);
 */
export function validatePassword(
  password: string,
  options: PasswordValidationOptions = {}
): PasswordValidationResult {
  const {
    minLength = 8,
    requireUppercase = true,
    requireLowercase = true,
    requireNumbers = true,
    requireSpecialChars = true,
  } = options;

  const errors: string[] = [];

  // Check if password is empty
  if (!password) {
    return {
      valid: false,
      errors: ['Password is required'],
      strength: 'weak',
    };
  }

  // Check minimum length
  if (password.length < minLength) {
    errors.push(`Password must be at least ${minLength} characters long`);
  }

  // Check for uppercase letter
  if (requireUppercase && !/[A-Z]/.test(password)) {
    errors.push('Password must contain at least one uppercase letter');
  }

  // Check for lowercase letter
  if (requireLowercase && !/[a-z]/.test(password)) {
    errors.push('Password must contain at least one lowercase letter');
  }

  // Check for number
  if (requireNumbers && !/[0-9]/.test(password)) {
    errors.push('Password must contain at least one number');
  }

  // Check for special character
  if (requireSpecialChars && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
    errors.push('Password must contain at least one special character');
  }

  // Calculate strength based on criteria met
  const strength = calculatePasswordStrength(password, {
    minLength,
    requireUppercase,
    requireLowercase,
    requireNumbers,
    requireSpecialChars,
  });

  return {
    valid: errors.length === 0,
    errors,
    strength,
  };
}

/**
 * Calculate password strength level based on criteria met
 *
 * @internal
 */
function calculatePasswordStrength(
  password: string,
  options: PasswordValidationOptions
): 'weak' | 'fair' | 'good' | 'strong' {
  let score = 0;
  const maxScore = 5;

  // Length score (0-2 points)
  if (password.length >= (options.minLength || 8)) {
    score += 1;
  }
  if (password.length >= 12) {
    score += 1;
  }

  // Character variety score (0-3 points)
  if (options.requireUppercase && /[A-Z]/.test(password)) {
    score += 1;
  }
  if (options.requireNumbers && /[0-9]/.test(password)) {
    score += 1;
  }
  if (options.requireSpecialChars && /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
    score += 1;
  }

  // Determine strength based on score
  if (score <= 1) {
    return 'weak';
  } else if (score <= 2) {
    return 'fair';
  } else if (score <= 3) {
    return 'good';
  } else {
    return 'strong';
  }
}

